-- Vorrats-Aufgaben (rollend-13) in bestehende Flüge einfügen: 132 Aufgaben, 12 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (3, 'terme.umformen', 777, 10, $auf$[{"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt, welche Werte ein Term T(x) für die Zahlen x = 1, 2, 3 und 4 annimmt. Welcher der drei Terme hat für alle vier Zahlen diese Werte?", "grafik": {"typ": "tabelle", "kopf": ["x", "1", "2", "3", "4"], "zeilen": [["T(x)", "6", "11", "16", "21"]]}}, "a": ["3x + 2 − 2x + 1", "3x + 2 + 2x − 1", "3x + 2 + 2x + 1"], "o": {"index": 1}, "h": "Fasse jeden Term zusammen oder setze x = 1 ein und vergleiche mit der ersten Spalte.", "w": "3x + 2 + 2x − 1 = 5x + 1. Für x = 1, 2, 3, 4 ergibt das 6, 11, 16, 21. Das passt zur Tabelle. Die anderen Terme sind zu x + 3 und 5x + 3 zusammenfassbar und haben schon bei x = 1 einen anderen Wert.", "form": "bruecke", "zaehlt": "ja", "r": 13778}, {"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl k gilt 7x + 3 − kx + 2x − 8 = 4x − 5 für alle Zahlen x?"}, "o": {"wert": 5}, "h": "Fasse links zuerst die x-Glieder und die Zahlen getrennt zusammen. Links und rechts muss bei x dieselbe Zahl stehen.", "w": "Links: 7x + 2x − kx = (9 − k)x und 3 − 8 = −5. Es muss 9 − k = 4 gelten, also k = 5. Probe: 7x + 3 − 5x + 2x − 8 = 4x − 5.", "form": "umkehren", "zaehlt": "ja", "r": 13779}, {"l": "produkte", "t": "produkte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Aus einem Tank fließt Wasser ab. Pro Minute ändert sich die Füllmenge um (−4a) Liter. Das Ventil bleibt 3b Minuten offen. Dabei ist a = 5 und b = 2. Eine Abnahme zählt als negative Zahl. Um wie viele Liter ändert sich die Füllmenge insgesamt?"}, "o": {"wert": -120, "einheit": "Liter"}, "h": "Die gesamte Änderung ist die Änderung pro Minute mal die Zahl der Minuten. Vereinfache zuerst (−4a)·(3b).", "w": "(−4a)·(3b) = −12ab. Für a = 5 und b = 2 ist das −12 · 5 · 2 = −120. Die Füllmenge nimmt um 120 Liter ab.", "form": "anwenden", "zaehlt": "ja", "r": 13780}, {"l": "produkte", "t": "produkte", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vereinfacht (−2a²) · (−3a) · (5b). Zeile 1: Ordnen: (−2a²) · (−3a) · (5b) = (−2) · (−3) · 5 · a² · a · b Zeile 2: Zahlen: (−2) · (−3) · 5 = −30. Potenzen: a² · a = a³. Zeile 3: Ergebnis: −30a³b In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welches Vorzeichen hat (−2) · (−3)?", "w": "Zwei negative Faktoren ergeben ein positives Produkt: (−2) · (−3) = 6 und 6 · 5 = 30. Richtig ist 30a³b. Zeile 3 übernimmt nur das Ergebnis der Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13781}, {"l": "minusklammer", "t": "minusklammer", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Wasserbecken enthält (6x + 40) Liter. Dann werden (2x − 15) Liter entnommen. Wie viele Liter bleiben im Becken, wenn x = 10 ist?"}, "o": {"wert": 95, "einheit": "Liter"}, "h": "Du ziehst die ganze entnommene Menge ab. Setze sie in eine Klammer, bevor du das Minus anwendest.", "w": "(6x + 40) − (2x − 15) = 6x + 40 − 2x + 15 = 4x + 55. Für x = 10: 40 + 55 = 95 Liter. Probe: 100 − 5 = 95.", "form": "anwenden", "zaehlt": "ja", "r": 13782}, {"l": "minusklammer", "t": "minusklammer", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl b gilt 5x − (2x + b) − (x − 3) = 2x − 1 für alle Zahlen x?"}, "o": {"wert": 4}, "h": "Löse beide Klammern auf. Sammle dann die x-Glieder und die Zahlen getrennt. Die Zahlen links müssen −1 ergeben.", "w": "5x − 2x − b − x + 3 = 2x + (3 − b). Es muss 3 − b = −1 gelten, also b = 4. Probe: 5x − (2x + 4) − (x − 3) = 2x − 1.", "form": "umkehren", "zaehlt": "ja", "r": 13783}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "In einem Saal stehen 17 Reihen mit je 24 Stühlen. Berechne die Zahl der Stühle im Kopf mit dem Verteilungsgesetz auf zwei Wegen. Weg A: 17 · (20 + 4). Weg B: 24 · (20 − 3). Wie viele Stühle sind es?"}, "o": {"wert": 408, "einheit": "Stühle"}, "h": "Beide Wege müssen dasselbe Ergebnis haben. Jeder Summand in der Klammer wird mit dem anderen Faktor malgenommen.", "w": "Weg A: 17 · 20 + 17 · 4 = 340 + 68 = 408. Weg B: 24 · 20 − 24 · 3 = 480 − 72 = 408. Beide Wege führen auf 408 Stühle.", "form": "zwei_wege", "zaehlt": "ja", "r": 13784}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst die Klammer auf und fasst zusammen: −2x(3x − 4) + 5x. Zeile 1: −2x(3x − 4) = −6x² − 8x Zeile 2: Dazu 5x: −6x² − 8x + 5x = −6x² − 3x Zeile 3: Ergebnis: −6x² − 3x In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Rechne −2x · (−4) einzeln. Welches Vorzeichen hat das Ergebnis?", "w": "−2x · (−4) = +8x, nicht −8x. Richtig: −2x(3x − 4) = −6x² + 8x. Dann −6x² + 8x + 5x = −6x² + 13x. Die Zeilen 2 und 3 folgen richtig aus dem Fehler der Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13785}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für ein Fest kauft ein Verein n Brezeln zu je 2 € und n Getränke zu je 1 €. Dazu kommt ein Plakat für 8 €. Der Gesamtpreis in Euro ist 3n + 8. Ein Helfer schreibt ihn auf drei andere Arten auf: (1) 2(n + 4) + n, (2) 3(n + 8), (3) 8 + 2n + n. Wie viele dieser drei Terme geben für jede Zahl n denselben Preis wie 3n + 8?"}, "o": {"wert": 2}, "h": "Fasse jeden Term zusammen. Bei linearen Termen (nur n, kein n²) genügt auch: setze n = 0 und n = 1 ein.", "w": "(1) 2n + 8 + n = 3n + 8. Gleich. (2) 3n + 24. Nicht gleich, schon bei n = 0 ist es 24 statt 8. (3) 8 + 3n. Gleich. Es sind 2 Terme.", "form": "anwenden", "zaehlt": "ja", "r": 13786}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, ob die Terme x² + 2 und 3x für alle Zahlen x denselben Wert haben. Zeile 1: x = 1: 1² + 2 = 3 und 3 · 1 = 3. Die Werte sind gleich. Zeile 2: x = 2: 2² + 2 = 6 und 3 · 2 = 6. Die Werte sind gleich. Zeile 3: Zwei Beispiele stimmen, also haben die Terme für alle Zahlen x denselben Wert. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Probiere auch x = 3 und x = 0 aus.", "w": "Für x = 3 ist x² + 2 = 11, aber 3x = 9. Die Terme sind nicht gleichwertig. Passende Beispiele beweisen nichts; ein einziges Gegenbeispiel genügt zum Widerlegen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13787}]$auf$::jsonb),
    (5, 'gleichungen.linear', 604, 12, $auf$[{"l": "waage", "t": "umformen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Balkenwaage ist im Gleichgewicht. Links liegen 4 Äpfel gleicher Masse und Gewichtsstücke mit zusammen 150 g. Rechts liegen 2 dieser Äpfel und Gewichtsstücke mit zusammen 350 g. Wie viel Gramm wiegt ein Apfel?"}, "o": {"wert": 100, "einheit": "g"}, "h": "Nimm auf beiden Seiten gleich viel weg, damit die Waage im Gleichgewicht bleibt. Entferne zuerst 2 Äpfel.", "w": "Die Gleichung ist 4a + 150 = 2a + 350. Nimm links und rechts 2 Äpfel weg: 2a + 150 = 350. Nimm 150 g weg: 2a = 200. Ein Apfel wiegt a = 100 g. Probe: 400 + 150 = 550 und 200 + 350 = 550.", "form": "anwenden", "zaehlt": "ja", "r": 13605}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst die Gleichung 5x − 12 = 2x + 9. Zeile 1: Auf beiden Seiten 2x abziehen und 12 addieren: 3x = 9 + 12. Zeile 2: Zusammengefasst: 3x = 21. Zeile 3: Beide Seiten mal 3: x = 63 In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wie wird aus 3x das einzelne x? Probe mit einer kleinen Zahl.", "w": "3x bedeutet 3 mal x. Die Umkehrung ist das Teilen durch 3: x = 21 : 3 = 7. Probe: 5 · 7 − 12 = 23 und 2 · 7 + 9 = 23.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13606}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Zeichnung zeigt die Geraden zu y = 3x − 2 und y = x + 4. Wo sich die Geraden schneiden, haben beide Terme denselben Wert. Das ist die Lösung der Gleichung 3x − 2 = x + 4. Bei welcher Zahl x ist das der Fall?", "grafik": {"typ": "koordinaten", "x": [-1, 5], "y": [-3, 9], "graphen": [{"art": "linear", "m": 3, "t": -2, "name": "y = 3x − 2"}, {"art": "linear", "m": 1, "t": 4, "name": "y = x + 4"}]}}, "o": {"wert": 3}, "h": "Wo schneiden sich die beiden Geraden? Lies die x-Koordinate des Schnittpunkts ab und rechne zur Probe nach.", "w": "Die Geraden schneiden sich bei x = 3. Rechnung: 3x − x = 4 + 2, also 2x = 6 und x = 3. Probe: 3 · 3 − 2 = 7 und 3 + 4 = 7.", "form": "bruecke", "zaehlt": "ja", "r": 13607}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl a hat die Gleichung 5x + a = 2x + 9 die Lösung x = 4?"}, "o": {"wert": -3}, "h": "Eine Lösung macht die Gleichung wahr. Was passiert, wenn du sie einsetzt?", "w": "Links: 5 · 4 + a = 20 + a. Rechts: 2 · 4 + 9 = 17. Aus 20 + a = 17 folgt a = −3. Probe: 5x − 3 = 2x + 9 hat die Lösung x = 4, denn 17 = 17.", "form": "umkehren", "zaehlt": "ja", "r": 13608}, {"l": "klammern", "t": "umformen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Im Kino kostet eine Kinderkarte x €. Eine Erwachsenenkarte kostet 2 € mehr, eine Premiumkarte 9 € mehr als eine Kinderkarte. Gruppe A kauft 3 Erwachsenenkarten und zahlt dazu 5 € für die Garderobe. Gruppe B kauft 2 Premiumkarten. Beide Gruppen zahlen gleich viel. Wie viel Euro kostet eine Kinderkarte?"}, "o": {"wert": 7, "einheit": "€"}, "h": "Eine Erwachsenenkarte kostet (x + 2) €, eine Premiumkarte (x + 9) €. Stelle für jede Gruppe den Gesamtpreis auf.", "w": "Gruppe A: 3(x + 2) + 5. Gruppe B: 2(x + 9). Gleichung: 3(x + 2) + 5 = 2(x + 9). Ausmultiplizieren: 3x + 11 = 2x + 18. Dann x = 7. Probe: 3 · 9 + 5 = 32 und 2 · 16 = 32.", "form": "anwenden", "zaehlt": "ja", "r": 13609}, {"l": "klammern", "t": "umformen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl a hat die Gleichung 4(x − a) = 2x + 6 die Lösung x = 5?"}, "o": {"wert": 1}, "h": "Setze x = 5 ein. Was kannst du dann auf der rechten Seite ausrechnen?", "w": "Rechts: 2 · 5 + 6 = 16. Links: 4(5 − a) = 16, also 5 − a = 4 und a = 1. Probe: 4(5 − 1) = 16.", "form": "umkehren", "zaehlt": "ja", "r": 13610}, {"l": "probe", "t": "pruefen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim hat die Gleichung 2(x + 5) − 3 = 4x − 7 gelöst und x = 9 erhalten. Bei der Probe vergleicht man die beiden Seiten. Weg A: Beide Seiten für x = 9 einzeln ausrechnen und den Unterschied bilden. Weg B: Zuerst den Unterschied 2(x + 5) − 3 − (4x − 7) zu einem Term in x zusammenfassen und dann x = 9 einsetzen. Wie groß ist der Unterschied „linke Seite minus rechte Seite“ für x = 9?"}, "o": {"wert": -4}, "h": "Beide Wege müssen denselben Unterschied ergeben. Wäre x = 9 eine Lösung, müsste der Unterschied null sein.", "w": "Weg A: Links ist 2 · 14 − 3 = 25, rechts ist 4 · 9 − 7 = 29. Der Unterschied ist 25 − 29 = −4. Weg B: 2x + 10 − 3 − 4x + 7 = −2x + 14. Für x = 9 ist das −18 + 14 = −4. Der Unterschied ist nicht null, also ist x = 9 keine Lösung. Richtig ist x = 7.", "form": "zwei_wege", "zaehlt": "ja", "r": 13611}, {"l": "probe", "t": "pruefen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst 4(x − 2) = 3x + 1 und macht eine Probe. Zeile 1: Ausmultiplizieren: 4(x − 2) = 4x − 2, also 4x − 2 = 3x + 1. Zeile 2: Beide Seiten minus 3x und plus 2: x = 3. Zeile 3: Probe in der Gleichung 4x − 2 = 3x + 1: links 4 · 3 − 2 = 10, rechts 3 · 3 + 1 = 10. Also stimmt x = 3. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie lautet die Ausgangsgleichung? Setze x = 3 genau dort ein.", "w": "4(x − 2) = 4x − 8, nicht 4x − 2: Die 2 wird auch mit 4 malgenommen. Dann ist 4x − 8 = 3x + 1 und x = 9. Die Probe in Zeile 3 benutzt die fehlerhafte Gleichung aus Zeile 1. Eine Probe gehört in die Ausgangsgleichung: 4(3 − 2) = 4, aber 3 · 3 + 1 = 10.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13612}, {"l": "sonderfaelle", "t": "pruefen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Zeichnung zeigt die Geraden zu y = 2x + 3 und y = 2x + 5. Gesucht sind alle Zahlen x (aus ℚ), für die 2x + 3 = 2x + 5 gilt. Was sagt die Zeichnung über diese Gleichung?", "grafik": {"typ": "koordinaten", "x": [-3, 3], "y": [-2, 12], "graphen": [{"art": "linear", "m": 2, "t": 3, "name": "y = 2x + 3"}, {"art": "linear", "m": 2, "t": 5, "name": "y = 2x + 5"}]}}, "a": ["Die Gleichung hat genau eine Lösung, nämlich x = 0, denn dort schneiden die Geraden die y-Achse.", "Jede Zahl ist Lösung, denn beide Geraden haben dieselbe Steigung.", "Die Gleichung hat keine Lösung, denn die Geraden sind parallel und haben keinen gemeinsamen Punkt."], "o": {"index": 2}, "h": "Wo hätten die Geraden einen gemeinsamen Punkt? Vergleiche die y-Werte bei x = 0 und bei x = 1.", "w": "Beide Geraden haben die Steigung 2 und sind parallel. Bei gleichem x liegt die zweite Gerade 2 Einheiten höher, die Geraden haben keinen gemeinsamen Punkt. Rechnung: 2x + 3 = 2x + 5 führt auf 3 = 5, das ist falsch. Die Lösungsmenge ist leer.", "form": "bruecke", "zaehlt": "ja", "r": 13613}, {"l": "sonderfaelle", "t": "pruefen", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "Es gibt genau eine Zahl k, für die die Gleichung 3(x + 2) = 3x + k für alle Zahlen x wahr ist. Weg A: Klammer ausmultiplizieren und beide Seiten vergleichen. Weg B: eine passende Zahl für x einsetzen, zum Beispiel x = 0, und daraus k bestimmen. Wie groß ist k?"}, "o": {"wert": 6}, "h": "Bei beiden Wegen musst du am Ende k = ... bestimmen. Welche Zahl steht links, wenn x = 0 ist?", "w": "Weg A: 3(x + 2) = 3x + 6. Soll 3x + 6 = 3x + k für alle x gelten, muss k = 6 sein. Weg B: Für x = 0 steht links 3 · 2 = 6 und rechts k. Also k = 6. Probe: 3(x + 2) = 3x + 6 stimmt für jedes x.", "form": "zwei_wege", "zaehlt": "ja", "r": 13614}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Zwei Rucksäcke wiegen zusammen 54 kg. Der schwerere ist 8 kg schwerer als der leichtere. Weg A: Stelle eine Gleichung auf. Weg B: Nimm den Unterschied erst weg, teile den Rest gerecht auf und gib dem schwereren Rucksack den Unterschied dann wieder dazu. Wie viele Kilogramm wiegt der schwerere Rucksack?"}, "o": {"wert": 31, "einheit": "kg"}, "h": "Beide Wege liefern dieselbe Masse. Bei Weg A ist die Masse des leichteren Rucksacks x kg.", "w": "Weg A: x + (x + 8) = 54, also 2x = 46 und x = 23. Der schwerere Rucksack wiegt 23 + 8 = 31 kg. Weg B: 54 − 8 = 46, gerecht geteilt 23 kg, dann 8 kg dazu: 31 kg. Probe: 23 + 31 = 54.", "form": "zwei_wege", "zaehlt": "ja", "r": 13615}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Tom bestellt eine Jacke im Internet. Der Rabatt von 20 % gilt nur für die Jacke. Danach kommen 5 € Versandkosten dazu. Tom zahlt insgesamt 53 €. Wie viel Euro hat die Jacke ohne Rabatt gekostet?"}, "o": {"wert": 60, "einheit": "€"}, "h": "Gehe rückwärts: Was hat Tom für die Jacke allein bezahlt? Wie viel Prozent des ursprünglichen Preises sind das?", "w": "Gleichung: 0,8x + 5 = 53. Dann 0,8x = 48 und x = 48 : 0,8 = 60. Die Jacke kostete 60 €. Probe: 20 % von 60 € sind 12 €, 60 − 12 = 48 und 48 + 5 = 53.", "form": "umkehren", "zaehlt": "ja", "r": 13616}]$auf$::jsonb),
    (16, 'funktionen.grundbegriffe', 742, 18, $auf$[{"l": "eindeutig", "t": "eindeutig", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Fünf Kinder wohnen in einer Straße. Die Tabelle zeigt die Hausnummer jedes Kindes. Jedes Kind wohnt in genau einem Haus. Betrachte die Zuordnungen (a) Kind → Hausnummer und (b) Hausnummer → Kind (in der Tabelle vorkommende Hausnummern). Welche Aussage stimmt?", "grafik": {"typ": "tabelle", "kopf": ["Kind", "Kim", "Tom", "Ali", "Zoe", "Mia"], "zeilen": [["Hausnummer", "4", "7", "4", "9", "7"]]}}, "a": ["Nur (b) ist eine Funktion.", "Beide Zuordnungen sind Funktionen.", "Nur (a) ist eine Funktion.", "Keine der beiden Zuordnungen ist eine Funktion."], "o": {"index": 2}, "h": "Eine Funktion ordnet jeder Eingabe genau eine Ausgabe zu. Prüfe, ob zu einer Eingabe zwei verschiedene Ausgaben gehören.", "w": "(a) Jedes Kind hat genau eine Hausnummer: Kim 4, Tom 7, Ali 4, Zoe 9, Mia 7. Das ist eine Funktion. (b) Zur Hausnummer 4 gehören Kim und Ali, zur Hausnummer 7 gehören Tom und Mia. Eine Eingabe hat zwei Ausgaben, also keine Funktion. Dass zwei Kinder dieselbe Hausnummer haben, ist bei (a) kein Problem.", "form": "anwenden", "zaehlt": "ja", "r": 13743}, {"l": "eindeutig", "t": "eindeutig", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Zuordnung hat die Paare (1 | 4), (2 | a + 3), (3 | 5) und (2 | 9). Sie soll eine Funktion sein. Welche Zahl muss a sein?"}, "o": {"wert": 6}, "h": "Bei einer Funktion gehört zu jedem x genau ein y. Zu welchem x gibt es mehr als ein Paar?", "w": "Zum x = 2 gibt es zwei Paare: (2 | a + 3) und (2 | 9). Eine Funktion ordnet 2 nur einen y-Wert zu, also muss a + 3 = 9 gelten und a = 6. Probe: Mit a = 6 ist (2 | 9) beide Male dasselbe Paar, das ist erlaubt.", "form": "umkehren", "zaehlt": "ja", "r": 13744}, {"l": "mengen", "t": "mengen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt die Funktion f(x) = x² − 1 für die Definitionsmenge D = {−2; −1; 0; 1; 2}. Welche Menge ist die Wertemenge W?", "grafik": {"typ": "tabelle", "kopf": ["x", "−2", "−1", "0", "1", "2"], "zeilen": [["f(x)", "3", "0", "−1", "0", "3"]]}}, "a": ["W = {−1; 0; 3}", "W = {−2; −1; 0; 1; 2}", "W = {0; 3}"], "o": {"index": 0}, "h": "Wertemenge: Welche verschiedenen Funktionswerte stehen in der unteren Zeile? Jeder Wert wird nur einmal genannt.", "w": "Die Funktionswerte sind 3, 0, −1, 0, 3. Verschiedene Werte: −1, 0 und 3. Also W = {−1; 0; 3}. Die Zahlen aus D sind die Eingaben, nicht die Funktionswerte.", "form": "bruecke", "zaehlt": "ja", "r": 13745}, {"l": "mengen", "t": "mengen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Funktion f(x) = x² − 4x hat die Definitionsmenge D = {−1; 0; 1; 2; 3; 4; 5}. Weg A: alle sieben Funktionswerte ausrechnen. Weg B: nur f(2) und die Hälfte der Stellen ausrechnen, denn die Werte sind symmetrisch zur Stelle x = 2: Stellen mit gleichem Abstand von 2 haben denselben Funktionswert. Wie viele Elemente hat die Wertemenge W?"}, "o": {"wert": 4}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Gleiche Funktionswerte werden in der Wertemenge nur einmal gezählt.", "w": "Weg A: f(−1) = 5, f(0) = 0, f(1) = −3, f(2) = −4, f(3) = −3, f(4) = 0, f(5) = 5. Verschiedene Werte: −4, −3, 0, 5. Weg B: f(1) = f(3), f(0) = f(4), f(−1) = f(5). Nur f(−1), f(0), f(1), f(2) sind nötig: 5, 0, −3, −4. Es sind 4 Elemente.", "form": "zwei_wege", "zaehlt": "ja", "r": 13746}, {"l": "funktionswert", "t": "funktionswert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Stein wird von einer Brücke fallen gelassen, die 120 m über dem Wasser liegt. Ohne Luftwiderstand gilt für die Höhe über dem Wasser nach t Sekunden: h(t) = 120 − 5t². Wie hoch ist der Stein nach 4 Sekunden über dem Wasser (in Metern)?"}, "o": {"wert": 40, "einheit": "m"}, "h": "Rechne zuerst das Quadrat, dann mal 5, dann ziehe das Ergebnis von 120 ab.", "w": "h(4) = 120 − 5 · 4² = 120 − 5 · 16 = 120 − 80 = 40. Nach 4 Sekunden ist der Stein noch 40 m über dem Wasser.", "form": "anwenden", "zaehlt": "ja", "r": 13747}, {"l": "funktionswert", "t": "funktionswert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl a hat die Funktion f(x) = a · x² + 3 an der Stelle x = 2 den Funktionswert 15?"}, "o": {"wert": 3}, "h": "Setze x = 2 ein und rechne 2² zuerst. Dann bleibt eine Gleichung nur mit a.", "w": "f(2) = a · 2² + 3 = 4a + 3. Aus 4a + 3 = 15 folgt 4a = 12 und a = 3. Probe: f(2) = 3 · 4 + 3 = 15.", "form": "umkehren", "zaehlt": "ja", "r": 13748}, {"l": "stelle", "t": "stelle", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Zeichnung zeigt den Graphen einer linearen Funktion f. Für welche Stelle x gilt f(x) = 3?", "grafik": {"typ": "koordinaten", "x": [-1, 6], "y": [-1, 8], "graphen": [{"art": "linear", "m": -1.5, "t": 6, "name": "f"}], "punkte": [{"x": 0, "y": 6}, {"x": 4, "y": 0}]}}, "o": {"wert": 2}, "h": "Suche auf der y-Achse die Höhe 3 und gehe waagerecht bis zum Graphen. Lies dort die x-Koordinate ab.", "w": "Auf dem Graphen liegen zum Beispiel die Punkte (0 | 6) und (4 | 0). Bei der Höhe y = 3 liegt der Punkt (2 | 3). Die gesuchte Stelle ist x = 2. Probe mit der Gleichung f(x) = −1,5x + 6: −1,5 · 2 + 6 = 3.", "form": "bruecke", "zaehlt": "ja", "r": 13749}, {"l": "stelle", "t": "stelle", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Fitnessstudio berechnet für n Besuche im Monat die Kosten K(n) = 20 + 4n (in Euro). Kim möchte, dass der Preis pro Besuch, also K(n)/n, genau 6 € beträgt. Bei wie vielen Besuchen im Monat ist das der Fall?"}, "o": {"wert": 10, "einheit": "Besuche"}, "h": "Wie berechnest du den Preis pro Besuch aus K(n) und n?", "w": "Gleichung: (20 + 4n)/n = 6. Mal n: 20 + 4n = 6n. Dann 20 = 2n und n = 10. Probe: K(10) = 60 €, und 60 : 10 = 6 €.", "form": "anwenden", "zaehlt": "ja", "r": 13750}, {"l": "wertetabelle", "t": "wertetabelle", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Die Temperatur in Grad Fahrenheit hängt von der Temperatur C in Grad Celsius ab: F(C) = 32 + 1,8 · C. Die Tabelle zeigt einige Werte. Wie viel Grad Fahrenheit sind 25 °C?", "grafik": {"typ": "tabelle", "kopf": ["C in °C", "0", "10", "20", "30"], "zeilen": [["F in °F", "32", "50", "68", "86"]]}}, "o": {"wert": 77, "einheit": "°F"}, "h": "Setze C = 25 in die Gleichung ein. Rechne zuerst das Malnehmen, dann das Addieren.", "w": "F(25) = 32 + 1,8 · 25 = 32 + 45 = 77. 25 °C sind 77 °F. Passende Kontrolle mit der Tabelle: bei 20 °C sind es 68 °F und bei 30 °C sind es 86 °F, 77 liegt genau in der Mitte.", "form": "anwenden", "zaehlt": "ja", "r": 13751}, {"l": "wertetabelle", "t": "wertetabelle", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Tabelle gehört zur Funktion f(x) = x² − 6x + 5. Weg A: f(6) direkt ausrechnen. Weg B: Die Werte der Tabelle sind symmetrisch zur Stelle x = 3. Lies den Wert an der Stelle ab, die genauso weit von 3 entfernt ist wie 6. Welcher Wert gehört an die Stelle x = 6?", "grafik": {"typ": "tabelle", "kopf": ["x", "0", "1", "2", "3", "4", "5", "6"], "zeilen": [["f(x)", "5", "0", "−3", "−4", "−3", "0", "?"]]}}, "o": {"wert": 5}, "h": "Beide Wege müssen denselben Wert ergeben. Die Stelle 6 ist 3 Schritte rechts von 3. Welche Stelle ist 3 Schritte links davon?", "w": "Weg A: f(6) = 36 − 36 + 5 = 5. Weg B: 6 hat den Abstand 3 von der Stelle 3; die Stelle 0 hat auch den Abstand 3 auf der anderen Seite. Aus der Tabelle: f(0) = 5. Also f(6) = 5.", "form": "zwei_wege", "zaehlt": "ja", "r": 13752}, {"l": "graph_lesen", "t": "graph_lesen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Ball wird senkrecht nach oben geworfen. Die Zeichnung zeigt seine Höhe h in Metern in Abhängigkeit von der Zeit t in Sekunden (ohne Luftwiderstand). Wie viele Meter hoch fliegt der Ball höchstens?", "grafik": {"typ": "koordinaten", "x": [0, 5], "y": [-2, 25], "graphen": [{"art": "poly", "k": [0, 20, -5]}], "name_x": "t in s", "name_y": "h in m"}}, "o": {"wert": 20, "einheit": "m"}, "h": "Wo liegt der höchste Punkt des Graphen? Lies seine Höhe an der senkrechten Achse ab.", "w": "Der höchste Punkt des Graphen liegt bei t = 2 Sekunden auf der Höhe 20 Meter. Der Ball fliegt 20 m hoch. Er landet nach 4 Sekunden wieder (Höhe 0).", "form": "anwenden", "zaehlt": "ja", "r": 13753}, {"l": "graph_lesen", "t": "graph_lesen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Zeichnung zeigt die Graphen von f(x) = 0,5x + 1 und g(x) = −x + 7. Weg A: Lies die x-Koordinate des Schnittpunkts am Bild ab. Weg B: Setze f(x) = g(x) und löse die Gleichung. Bei welcher Stelle x haben beide Funktionen denselben Funktionswert?", "grafik": {"typ": "koordinaten", "x": [-2, 8], "y": [-2, 9], "graphen": [{"art": "linear", "m": 0.5, "t": 1, "name": "f"}, {"art": "linear", "m": -1, "t": 7, "name": "g"}]}}, "o": {"wert": 4}, "h": "Beide Wege müssen dieselbe Stelle ergeben. Bei Weg B musst du 0,5x + 1 = −x + 7 nach x auflösen.", "w": "Weg A: Die Graphen schneiden sich im Punkt (4 | 3). Weg B: 0,5x + 1 = −x + 7, also 1,5x = 6 und x = 4. Probe: f(4) = 3 und g(4) = 3.", "form": "zwei_wege", "zaehlt": "ja", "r": 13754}, {"l": "nullstellen", "t": "nullstellen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Zeichnung zeigt den Graphen von f(x) = x² − x − 6. Welche Zahlen sind die Nullstellen von f?", "grafik": {"typ": "koordinaten", "x": [-4, 5], "y": [-8, 6], "graphen": [{"art": "poly", "k": [-6, -1, 1]}]}}, "a": ["x = 2 und x = −3", "x = −6", "x = −2 und x = 3"], "o": {"index": 2}, "h": "Nullstellen liegen dort, wo der Graph die x-Achse schneidet. Prüfe mit f(x) = 0 durch Einsetzen.", "w": "Der Graph schneidet die x-Achse bei x = −2 und bei x = 3. Probe: f(−2) = 4 + 2 − 6 = 0 und f(3) = 9 − 3 − 6 = 0. Mit x = 2 ergibt sich 4 − 2 − 6 = −4, mit x = −3 ergibt sich 9 + 3 − 6 = 6. Die Zahl −6 ist der Wert f(0), also der Schnittpunkt mit der y-Achse.", "form": "bruecke", "zaehlt": "ja", "r": 13755}, {"l": "nullstellen", "t": "nullstellen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Funktion f(x) = x² + b · x − 12 hat die Nullstelle x = 3. Welche Zahl ist b?"}, "o": {"wert": 1}, "h": "Setze x = 3 in die Funktion ein und setze das Ergebnis gleich 0. Es bleibt eine Gleichung nur mit b.", "w": "f(3) = 3² + 3b − 12 = 9 + 3b − 12 = 3b − 3. Aus 3b − 3 = 0 folgt b = 1. Probe: f(x) = x² + x − 12, f(3) = 9 + 3 − 12 = 0.", "form": "umkehren", "zaehlt": "ja", "r": 13756}, {"l": "punkt_graph", "t": "punkt_graph", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Gegeben sind f(x) = −x² + 4x und die Punkte A(1 | 3), B(2 | 3), C(3 | 3) und D(4 | 4). Weg A: Prüfe jeden Punkt durch Einsetzen. Weg B: Sieh im Bild nach, ob der Punkt auf der Kurve liegt. Welche der Punkte liegen auf dem Graphen von f?", "grafik": {"typ": "koordinaten", "x": [-1, 5], "y": [-3, 6], "graphen": [{"art": "poly", "k": [0, 4, -1]}], "punkte": [{"x": 1, "y": 3, "name": "A"}, {"x": 2, "y": 3, "name": "B"}, {"x": 3, "y": 3, "name": "C"}, {"x": 4, "y": 4, "name": "D"}]}}, "a": ["Nur A und C", "Nur B und D", "A, B und C", "Nur C"], "o": {"index": 0}, "h": "Setze für jeden Punkt die x-Koordinate in f ein und vergleiche mit der y-Koordinate.", "w": "f(1) = −1 + 4 = 3, also liegt A(1 | 3) auf dem Graphen. f(2) = −4 + 8 = 4, nicht 3, also liegt B nicht darauf. f(3) = −9 + 12 = 3, also liegt C darauf. f(4) = −16 + 16 = 0, nicht 4, also liegt D nicht darauf. Im Bild liegen A und C auf der Kurve.", "form": "zwei_wege", "zaehlt": "ja", "r": 13757}, {"l": "punkt_graph", "t": "punkt_graph", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Ball fliegt auf einer Bahn mit der Höhe h(x) = −0,05x² + x (x ist der waagerechte Abstand in Metern, h die Höhe in Metern). Bei x = 12 steht ein Baum, dessen Spitze in P(12 | 5,5) liegt. Um wie viele Meter liegt die Baumspitze über der Stelle des Ballgraphen bei x = 12?"}, "o": {"wert": 0.7, "einheit": "m"}, "h": "Vergleiche zwei Höhen an derselben Stelle x = 12.", "w": "h(12) = −0,05 · 144 + 12 = −7,2 + 12 = 4,8. Die Baumspitze liegt bei 5,5 m, der Ball fliegt dort nur 4,8 m hoch. Unterschied: 5,5 − 4,8 = 0,7 m. Der Punkt P liegt nicht auf dem Graphen, sondern 0,7 m darüber.", "form": "anwenden", "zaehlt": "ja", "r": 13758}, {"l": "sachzusammenhang", "t": "sachzusammenhang", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Wassertank enthält am Anfang 800 Liter. Er verliert gleichmäßig 50 Liter pro Stunde. Für die Wassermenge nach t Stunden gilt V(t) = 800 − 50t. Nach wie vielen Stunden ist der Tank leer?"}, "o": {"wert": 16, "einheit": "Stunden"}, "h": "Der Tank ist leer, wenn V(t) = 0 ist. Löse diese Gleichung nach t auf.", "w": "V(t) = 0 bedeutet 800 − 50t = 0, also 50t = 800 und t = 16. Nach 16 Stunden ist der Tank leer. Probe: V(16) = 800 − 800 = 0.", "form": "anwenden", "zaehlt": "ja", "r": 13759}, {"l": "sachzusammenhang", "t": "sachzusammenhang", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Kerze A ist 24 cm hoch und brennt gleichmäßig um 2 cm pro Stunde ab. Kerze B ist 30 cm hoch und brennt gleichmäßig um 3 cm pro Stunde ab. Beide werden gleichzeitig angezündet. Weg A: Gleichung 24 − 2t = 30 − 3t lösen. Weg B: eine Tabelle für t = 0, 1, 2, … anlegen und die Zeile mit gleichen Höhen suchen. Nach wie vielen Stunden sind beide erstmals gleich hoch, während beide noch brennen?"}, "o": {"wert": 6, "einheit": "Stunden"}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Bei Weg B ändert sich der Höhenunterschied der beiden Kerzen Stunde für Stunde um dieselbe Zahl.", "w": "Weg A: 24 − 2t = 30 − 3t, also t = 6. Weg B: Die Höhen nach 0, 1, 2, 3, 4, 5, 6 Stunden: A: 24, 22, 20, 18, 16, 14, 12 und B: 30, 27, 24, 21, 18, 15, 12. Nach 6 Stunden sind beide 12 cm hoch.", "form": "zwei_wege", "zaehlt": "ja", "r": 13760}]$auf$::jsonb),
    (17, 'funktionen.linear', 777, 22, $auf$[{"l": "ablesen", "t": "ablesen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Taxi berechnet den Fahrpreis P(x) = 3,5 + 2,2 · x in Euro (x in Kilometern). Um wie viel Euro wird die Fahrt teurer, wenn sie 5 km länger ist?"}, "o": {"wert": 11, "einheit": "€"}, "h": "Welche Zahl in P(x) sagt, um wie viel der Preis pro Kilometer steigt? Wie oft kommt sie dazu?", "w": "Die Steigung m = 2,2 ist der Preis je Kilometer. Für 5 km mehr kommen 5 · 2,2 = 11 € dazu. Die Grundgebühr 3,5 € fällt nur einmal an und ändert sich nicht.", "form": "anwenden", "zaehlt": "ja", "r": 13778}, {"l": "ablesen", "t": "ablesen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Gerade hat die Gleichung 4x − 2y = 10. Weg A: Löse die Gleichung nach y auf und lies m ab. Weg B: Bestimme zwei Punkte der Geraden (zum Beispiel für x = 0 und für x = 1) und berechne die Steigung aus ihnen. Wie groß ist die Steigung m der Geraden?"}, "o": {"wert": 2}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Beim Auflösen nach y wird durch −2 geteilt.", "w": "Weg A: 4x − 2y = 10 gibt −2y = −4x + 10, also y = 2x − 5. Die Steigung ist m = 2. Weg B: Für x = 0 ist y = −5, für x = 1 ist y = −3. Steigung = (−3 − (−5)) : (1 − 0) = 2.", "form": "zwei_wege", "zaehlt": "ja", "r": 13779}, {"l": "graph_ablesen", "t": "graph_ablesen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Heißluftballon steigt gleichmäßig. Die Zeichnung zeigt seine Höhe h in Metern in Abhängigkeit von der Zeit t in Minuten. Die Gerade geht durch die markierten Punkte (0 | 20) und (4 | 56). Mit welcher Geschwindigkeit steigt der Ballon (in Metern pro Minute)?", "grafik": {"typ": "koordinaten", "x": [0, 6], "y": [0, 80], "graphen": [{"art": "linear", "m": 9, "t": 20}], "punkte": [{"x": 0, "y": 20}, {"x": 4, "y": 56}], "name_x": "t in min", "name_y": "h in m"}}, "o": {"wert": 9, "einheit": "m/min"}, "h": "Lies zwei markierte Punkte ab. Wie viel Meter kommen in wie vielen Minuten dazu?", "w": "Die markierten Punkte sind (0 | 20) und (4 | 56). In 4 Minuten steigt der Ballon um 56 − 20 = 36 m. Geschwindigkeit: 36 : 4 = 9 Meter pro Minute.", "form": "anwenden", "zaehlt": "ja", "r": 13780}, {"l": "graph_ablesen", "t": "graph_ablesen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Zeichnung zeigt einen Teil einer Geraden g. Sie geht durch die markierten Punkte und läuft nach rechts und oben über das Bild hinaus weiter. Bei welcher Stelle x hat g den y-Wert 14?", "grafik": {"typ": "koordinaten", "x": [0, 8], "y": [0, 8], "graphen": [{"art": "linear", "m": 0.75, "t": 2, "name": "g"}], "punkte": [{"x": 0, "y": 2}, {"x": 4, "y": 5}]}}, "o": {"wert": 16}, "h": "Was kannst du am Graphen ablesen, um die Gleichung der Geraden aufzustellen?", "w": "Am Graphen: t = 2 (Punkt (0 | 2)). Von (0 | 2) nach (4 | 5) geht es 4 nach rechts und 3 nach oben, also m = 3 : 4 = 0,75. Gleichung: y = 0,75x + 2. Für y = 14: 0,75x + 2 = 14, also 0,75x = 12 und x = 16. Probe: 0,75 · 16 + 2 = 14.", "form": "umkehren", "zaehlt": "ja", "r": 13781}, {"l": "zwei_punkte", "t": "zwei_punkte", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt die Koordinaten von zwei Punkten. Eine Gerade geht durch beide Punkte. Welche Gleichung gehört zu dieser Geraden?", "grafik": {"typ": "tabelle", "kopf": ["x", "1", "4"], "zeilen": [["y", "5", "11"]]}}, "a": ["y = 6x − 1", "y = 2x + 5", "y = 2x + 3"], "o": {"index": 2}, "h": "Berechne zuerst die Steigung aus den beiden Punkten. Setze dann einen Punkt ein, um t zu bestimmen.", "w": "Steigung: (11 − 5) : (4 − 1) = 6 : 3 = 2. Aus 5 = 2 · 1 + t folgt t = 3. Probe mit dem zweiten Punkt: 2 · 4 + 3 = 11. Bei y = 6x − 1 ergibt x = 4 den Wert 23, bei y = 2x + 5 ergibt x = 1 den Wert 7.", "form": "bruecke", "zaehlt": "ja", "r": 13782}, {"l": "zwei_punkte", "t": "zwei_punkte", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Gerade geht durch A(−2 | 1) und B(4 | 7). Weg A: Bestimme die Gleichung y = m·x + t und setze x = 10 ein. Weg B: Gehe von B aus mit der Steigung weiter: so weit nach rechts, wie es bis x = 10 nötig ist, und um die dazu passende Strecke nach oben. Welchen y-Wert hat der Punkt der Geraden mit x = 10?"}, "o": {"wert": 13}, "h": "Beide Wege müssen denselben y-Wert ergeben. Zuerst brauchst du die Steigung aus A und B.", "w": "Steigung: (7 − 1) : (4 − (−2)) = 6 : 6 = 1. Weg A: 1 = 1 · (−2) + t gibt t = 3, also y = x + 3 und für x = 10 ist y = 13. Weg B: Von x = 4 bis x = 10 sind es 6 Schritte nach rechts, dabei geht es 6 · 1 = 6 nach oben: 7 + 6 = 13.", "form": "zwei_wege", "zaehlt": "ja", "r": 13783}, {"l": "proportional", "t": "proportional", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Zeichnung zeigt den Graphen einer proportionalen Funktion y = k · x. Der Graph geht durch den markierten Punkt. Wie groß ist k?", "grafik": {"typ": "koordinaten", "x": [-1, 6], "y": [-1, 9], "graphen": [{"art": "linear", "m": 1.5, "t": 0}], "punkte": [{"x": 4, "y": 6}]}}, "o": {"wert": 1.5}, "h": "Bei einer proportionalen Funktion ist k der Quotient y : x für jeden Punkt des Graphen (außer dem Ursprung).", "w": "Der markierte Punkt ist (4 | 6). Dann ist k = y : x = 6 : 4 = 1,5. Probe: y = 1,5 · 4 = 6.", "form": "bruecke", "zaehlt": "ja", "r": 13784}, {"l": "proportional", "t": "proportional", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Pumpe fördert gleichmäßig 18 Liter in 4 Minuten, eine zweite gleichmäßig 15 Liter in 2 Minuten. Beide Pumpen beginnen gleichzeitig, einen leeren Tank mit 108 Litern Fassungsvermögen zu füllen. Die Menge jeder Pumpe ist proportional zur Zeit. Nach wie vielen Minuten ist der Tank voll?"}, "o": {"wert": 9, "einheit": "Minuten"}, "h": "Wie viele Liter kommen pro Minute insgesamt dazu?", "w": "Pumpe 1: 18 : 4 = 4,5 Liter je Minute. Pumpe 2: 15 : 2 = 7,5 Liter je Minute. Zusammen 12 Liter je Minute. Für 108 Liter: 108 : 12 = 9 Minuten. Probe: 4,5 · 9 + 7,5 · 9 = 40,5 + 67,5 = 108.", "form": "anwenden", "zaehlt": "ja", "r": 13785}, {"l": "aufstellen", "t": "aufstellen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Eine Wandergruppe steigt gleichmäßig auf. Die Tabelle zeigt ihre Höhe h in Metern nach t Stunden. Welche Gleichung beschreibt die Höhe in Abhängigkeit von t?", "grafik": {"typ": "tabelle", "kopf": ["t in h", "0", "1", "2", "3"], "zeilen": [["h in m", "400", "550", "700", "850"]]}}, "a": ["h = 400 + 150t", "h = 150 + 400t", "h = 550 + 150t"], "o": {"index": 0}, "h": "Welche Höhe gehört zu t = 0? Wie viel kommt von einer Stunde zur nächsten dazu?", "w": "Bei t = 0 ist die Höhe 400 m (das ist der Wert ohne t im Term). Von Stunde zu Stunde kommen 150 m dazu (Steigung m = 150). Also h = 400 + 150t. Probe: t = 3 gibt 400 + 450 = 850.", "form": "bruecke", "zaehlt": "ja", "r": 13786}, {"l": "aufstellen", "t": "aufstellen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine lineare Funktion f hat f(2) = 7 und f(6) = 19. Wie groß ist f(0)?"}, "o": {"wert": 1}, "h": "Eine lineare Funktion ändert sich bei jedem Schritt in x um gleich viel.", "w": "Steigung: (19 − 7) : (6 − 2) = 12 : 4 = 3. Von x = 2 zurück zu x = 0 sind es 2 Schritte, also 2 · 3 = 6 weniger: f(0) = 7 − 6 = 1. Probe: f(x) = 3x + 1 gibt f(2) = 7 und f(6) = 19.", "form": "umkehren", "zaehlt": "ja", "r": 13787}, {"l": "schnittpunkte", "t": "schnittpunkte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Geraden g: y = 2x + 1 und h: y = −x + 7 schneiden sich in einem Punkt. Weg A: Lege für x = 0, 1, 2, 3, 4 eine Wertetabelle für beide Geraden an und suche die Spalte mit gleichen y-Werten. Weg B: Setze 2x + 1 = −x + 7 und löse die Gleichung. Wie groß ist die x-Koordinate des Schnittpunkts?"}, "o": {"wert": 2}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Im Schnittpunkt haben beide Geraden denselben y-Wert.", "w": "Weg A: g hat die Werte 1, 3, 5, 7, 9 und h hat die Werte 7, 6, 5, 4, 3. Gleich ist die Spalte x = 2 mit y = 5. Weg B: 2x + x = 7 − 1, also 3x = 6 und x = 2. Der Schnittpunkt ist S(2 | 5).", "form": "zwei_wege", "zaehlt": "ja", "r": 13788}, {"l": "schnittpunkte", "t": "schnittpunkte", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Geraden g: y = 2x + 1 und h: y = a·x + 7 schneiden sich an der Stelle x = 2. Welche Zahl ist a?"}, "o": {"wert": -1}, "h": "Im Schnittpunkt haben g und h denselben y-Wert.", "w": "g(2) = 2 · 2 + 1 = 5. Auch h hat dort den Wert 5: 2a + 7 = 5, also 2a = −2 und a = −1. Probe: h(2) = −2 + 7 = 5.", "form": "umkehren", "zaehlt": "ja", "r": 13789}, {"l": "lage", "t": "lage", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Zeichnung zeigt die Gerade g. Die Gerade h steht senkrecht auf g und geht durch den Punkt P(0 | 3). Welche Gleichung hat h?", "grafik": {"typ": "koordinaten", "x": [-3, 5], "y": [-4, 6], "graphen": [{"art": "linear", "m": 2, "t": -1, "name": "g"}], "punkte": [{"x": 0, "y": -1}, {"x": 1, "y": 1}, {"x": 0, "y": 3, "name": "P"}]}}, "a": ["y = −2x + 3", "y = −0,5x + 3", "y = 0,5x + 3"], "o": {"index": 1}, "h": "Lies die Steigung von g ab. Bei senkrechten Geraden ist das Produkt der Steigungen −1.", "w": "Die Gerade g geht durch (0 | −1) und (1 | 1): Steigung 2. Für die senkrechte Gerade gilt m · 2 = −1, also m = −0,5. Sie geht durch (0 | 3), also t = 3: y = −0,5x + 3.", "form": "bruecke", "zaehlt": "ja", "r": 13790}, {"l": "lage", "t": "lage", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Im Plan eines Parks (Einheit 1 m) liegt Weg A auf der Geraden y = 0,5x + 2. Im Punkt P(4 | 4) auf Weg A zweigt rechtwinklig ein Weg B ab. Bei welchem y-Wert schneidet Weg B die y-Achse?"}, "o": {"wert": 12, "einheit": "m"}, "h": "Was weißt du über die Steigungen zweier senkrechter Geraden? Weg B geht durch P.", "w": "Steigung von Weg B: m · 0,5 = −1, also m = −2. Durch P(4 | 4): 4 = −2 · 4 + t, also t = 12. Weg B schneidet die y-Achse bei y = 12. Probe: −2 · 4 + 12 = 4.", "form": "anwenden", "zaehlt": "ja", "r": 13791}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Gegeben ist die Schar y = (k + 1)·x − 2k. Weg A: Setze zuerst k = 3 ein und dann x = 4. Weg B: Setze zuerst x = 4 ein, vereinfache den Term in k und setze dann k = 3 ein. Wie groß ist y für k = 3 und x = 4?"}, "o": {"wert": 10}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Beim Vereinfachen werden die k-Glieder zusammengefasst.", "w": "Weg A: y = (3 + 1) · 4 − 2 · 3 = 16 − 6 = 10. Weg B: Mit x = 4 ist y = (k + 1) · 4 − 2k = 4k + 4 − 2k = 2k + 4. Für k = 3: 6 + 4 = 10.", "form": "zwei_wege", "zaehlt": "ja", "r": 13792}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Gerade der Schar y = (k − 2)·x + 2k geht durch den Punkt P(3 | 9). Welche Zahl ist k?"}, "o": {"wert": 3}, "h": "Setze die Koordinaten von P ein. Löse die Klammer auf und fasse die k-Glieder zusammen.", "w": "Aus 9 = (k − 2) · 3 + 2k folgt 9 = 3k − 6 + 2k = 5k − 6. Also 5k = 15 und k = 3. Probe: y = x + 6 gibt für x = 3 den Wert 9.", "form": "umkehren", "zaehlt": "ja", "r": 13793}, {"l": "wirkung", "t": "wirkung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Stromtarif berechnet K(x) = 8 + 0,3x in Euro (x in kWh). Der Preis je kWh steigt von 0,30 € auf 0,40 €, die Grundgebühr von 8 € bleibt gleich. Um wie viel Euro steigt die Rechnung für 50 kWh?"}, "o": {"wert": 5, "einheit": "€"}, "h": "Was ändert sich: die Grundgebühr oder der Preis je kWh? Wie wirkt sich die Änderung bei 50 kWh aus?", "w": "Die Grundgebühr bleibt gleich. Pro kWh kommen 0,40 − 0,30 = 0,10 € dazu. Für 50 kWh sind das 50 · 0,10 = 5 €. Probe: alt 8 + 15 = 23 €, neu 8 + 20 = 28 €.", "form": "anwenden", "zaehlt": "ja", "r": 13794}, {"l": "wirkung", "t": "wirkung", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Gerade y = (k − 1)·x + 3 hat eine Steigung, die doppelt so groß ist wie die Steigung von y = 2x + 3. Welche Zahl ist k?"}, "o": {"wert": 5}, "h": "Wie groß ist die Steigung der gesuchten Geraden? Wie hängt sie mit k zusammen?", "w": "Die Gerade y = 2x + 3 hat die Steigung 2. Doppelt so steil bedeutet die Steigung 4. Es gilt k − 1 = 4, also k = 5. Probe: y = 4x + 3.", "form": "umkehren", "zaehlt": "ja", "r": 13795}, {"l": "bueschel", "t": "bueschel", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Zeichnung zeigt drei Geraden einer Schar. Alle Geraden der Schar gehen durch denselben Punkt. Welche Gleichung beschreibt die Schar (m ist die Steigung der jeweiligen Geraden)?", "grafik": {"typ": "koordinaten", "x": [-2, 6], "y": [-2, 8], "graphen": [{"art": "linear", "m": -1, "t": 5}, {"art": "linear", "m": 0.5, "t": 2}, {"art": "linear", "m": 2, "t": -1}], "punkte": [{"x": 2, "y": 3}]}}, "a": ["y = m·(x + 2) + 3", "y = m·(x − 2) + 3", "y = m·(x − 3) + 2"], "o": {"index": 1}, "h": "Wo schneiden sich die drei Geraden? Welcher Punkt ergibt sich, wenn in y = m·(x − a) + b der Wert x = a eingesetzt wird?", "w": "Alle drei Geraden gehen durch den Punkt (2 | 3). In y = m·(x − 2) + 3 verschwindet der Klammerterm für x = 2, und y = 3 gilt für jede Steigung m. Die Geraden in der Zeichnung gehören zu m = −1, m = 0,5 und m = 2.", "form": "bruecke", "zaehlt": "ja", "r": 13796}, {"l": "bueschel", "t": "bueschel", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Zwei Laserstrahlen starten im Punkt P(2 | 3) und verlaufen geradlinig. Strahl A hat die Steigung 0,75, Strahl B hat die Steigung −0,25. Bei x = 6 steht eine senkrechte Wand. Wie viele Einheiten liegen die beiden Treffpunkte an der Wand auseinander?"}, "o": {"wert": 4, "einheit": "Einheiten"}, "h": "Auf welcher Geraden durch P liegt jeder Strahl?", "w": "Strahl A: y = 0,75 · (x − 2) + 3, bei x = 6 ist y = 0,75 · 4 + 3 = 6. Strahl B: y = −0,25 · (x − 2) + 3, bei x = 6 ist y = −1 + 3 = 2. Abstand der Treffpunkte: 6 − 2 = 4 Einheiten.", "form": "anwenden", "zaehlt": "ja", "r": 13797}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Die Höhe einer Sonnenblume wird durch H(t) = 12 + 1,5·t beschrieben (t in Tagen, H in Zentimetern). Welche Aussage stimmt?"}, "a": ["Die Sonnenblume war am Anfang 12 cm hoch und wächst jeden Tag um 1,5 cm.", "Die Sonnenblume war am Anfang 1,5 cm hoch und wächst jeden Tag um 12 cm.", "Die Sonnenblume ist nach 12 Tagen 1,5 cm hoch."], "o": {"index": 0}, "h": "Welche Höhe gehört zu t = 0? Um wie viel ändert sich H, wenn t um 1 größer wird?", "w": "Für t = 0 ist H = 12: Am Anfang ist die Pflanze 12 cm hoch. Jeder Tag bringt 1,5 cm dazu, denn 1,5 steht vor t. Nach 10 Tagen ist H = 27 cm.", "form": "anwenden", "zaehlt": "ja", "r": 13798}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Tarif A kostet K_A(x) = 5 + 0,2x, Tarif B kostet K_B(x) = 12 + 0,1x (x Minuten Gesprächszeit, Kosten in Euro, abgerechnet wird nur für ganze Minuten). Weg A: Löse die Ungleichung 12 + 0,1x < 5 + 0,2x. Weg B: Bestimme die Minute, bei der beide Tarife gleich viel kosten, und überlege mit den Steigungen, welcher Tarif danach billiger ist. Wie viele ganze Minuten muss man mindestens telefonieren, damit Tarif B billiger ist als Tarif A?"}, "o": {"wert": 71, "einheit": "Minuten"}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Der Tarif mit der größeren Steigung wird mit der Zeit teurer.", "w": "Weg A: 12 + 0,1x < 5 + 0,2x gibt 7 < 0,1x, also x > 70. Weg B: Gleich teuer bei 12 + 0,1x = 5 + 0,2x, also x = 70 (beide 19 €). Tarif A hat die größere Steigung, wird also danach teurer. Ab 71 Minuten ist B billiger. Probe: 71 Minuten kosten bei A 19,20 € und bei B 19,10 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 13799}]$auf$::jsonb),
    (20, 'gleichungen.bruch', 660, 14, $auf$[{"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Zeichnung zeigt den Graphen von y = 2/(x − 3). Für genau eine Zahl x gibt es auf dem Graphen keinen Punkt, nämlich dort, wo der Nenner x − 3 gleich 0 ist. Gesucht sind Zahlen x aus ℚ. Welche Zahl x darf in der Gleichung 2/(x − 3) = 1 nicht eingesetzt werden?", "grafik": {"typ": "koordinaten", "x": [-2, 8], "y": [-6, 6], "graphen": [{"art": "hyperbel", "a": 2, "b": -3, "c": 0, "name": "y = 2/(x − 3)"}]}}, "o": {"wert": 3}, "h": "Löse x − 3 = 0. An dieser Stelle bricht der Graph ab.", "w": "Der Nenner x − 3 ist 0 genau für x = 3 (die Lösung von x − 3 = 0). Dort ist der Term nicht definiert, der Graph hat an dieser Stelle eine Lücke. Die Definitionsmenge der Gleichung ist ℚ \\ {3}. (Die Gleichung selbst hat die Lösung x = 5: 2/2 = 1.)", "form": "bruecke", "zaehlt": "ja", "r": 13661}, {"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim bestimmt die Definitionsmenge der Gleichung 5/(x + 4) = 2/(x − 1) und stellt sie über Kreuz auf. Zeile 1: Nenner null setzen: x + 4 = 0 gibt x = 4, und x − 1 = 0 gibt x = 1. Zeile 2: Also ist D = ℚ \\ {4; 1}. Zeile 3: Über Kreuz: 5(x − 1) = 2(x + 4). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Löse x + 4 = 0 einzeln. Welche Zahl ergibt 0, wenn du 4 addierst?", "w": "x + 4 = 0 hat die Lösung x = −4, nicht 4. Richtig: D = ℚ \\ {−4; 1}. Zeile 2 übernimmt den Fehler der Zeile 1, Zeile 3 ist als Rechenschritt richtig.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13662}, {"l": "ein_bruch", "t": "ein_bruch", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Wenn man 36 durch eine Zahl x teilt und zum Ergebnis 5 addiert, erhält man 14. Welche Zahl ist x (x ≠ 0)?"}, "o": {"wert": 4}, "h": "Schreibe die Aussage zuerst als Gleichung: Was passiert zuerst mit x, was danach?", "w": "Erst wird 36 durch x geteilt: 36/x. Dann wird 5 addiert. Gleichung: 36/x + 5 = 14. Also 36/x = 9. Mit x multipliziert ist 36 = 9x und x = 4. Probe: 36/4 + 5 = 9 + 5 = 14.", "form": "bruecke", "zaehlt": "ja", "r": 13663}, {"l": "ein_bruch", "t": "ein_bruch", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl a hat die Gleichung a/x + 2 = 5 die Lösung x = 4?"}, "o": {"wert": 12}, "h": "Setze x = 4 ein. Welchen Wert muss a/4 haben, damit zusammen mit 2 die Zahl 5 herauskommt?", "w": "Mit x = 4: a/4 + 2 = 5. Dann a/4 = 3 und a = 12. Probe: 12/4 + 2 = 3 + 2 = 5.", "form": "umkehren", "zaehlt": "ja", "r": 13664}, {"l": "ueber_kreuz", "t": "ueber_kreuz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Löse 3/(x + 2) = 5/(x + 6) auf zwei Wegen (x ≠ −2 und x ≠ −6). Weg A: über Kreuz multiplizieren. Weg B: beide Seiten für x = 0, 1, 2, 3, 4, 5 ausrechnen (als auf zwei Stellen gerundete Dezimalzahlen, also Näherungen) und die Zahl suchen, bei der beide Seiten gleich sind. Welche Zahl ist die Lösung?"}, "o": {"wert": 4}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Bei Weg B hilft es, zuerst die Nenner x + 2 und x + 6 für jede Zahl auszurechnen.", "w": "Weg A: 3(x + 6) = 5(x + 2), also 3x + 18 = 5x + 10 und 8 = 2x. Weg B (gerundete Näherungswerte): Linke Seite für x = 0 bis 5: 1,5; 1; 0,75; 0,6; 0,5; 0,43. Rechte Seite: 0,83; 0,71; 0,63; 0,56; 0,5; 0,45. Gleich sind beide Seiten bei x = 4, nämlich 0,5. Probe: 3/6 = 5/10.", "form": "zwei_wege", "zaehlt": "ja", "r": 13665}, {"l": "ueber_kreuz", "t": "ueber_kreuz", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Läufer A läuft 6 km in t Minuten. Läufer B läuft 9 km und braucht 30 Minuten länger als Läufer A. Beide laufen gleichmäßig und haben dieselbe Durchschnittsgeschwindigkeit. Wie viele Minuten braucht Läufer A für seine 6 km?"}, "o": {"wert": 60, "einheit": "Minuten"}, "h": "Die Geschwindigkeit ist Strecke durch Zeit. Wie schnell ist jeder Läufer, ausgedrückt mit t?", "w": "Gleichung: 6/t = 9/(t + 30). Über Kreuz: 6(t + 30) = 9t, also 6t + 180 = 9t und t = 60. Läufer A braucht 60 Minuten, B 90 Minuten. Probe: 6 km in 60 min = 0,1 km/min und 9 km in 90 min = 0,1 km/min.", "form": "anwenden", "zaehlt": "ja", "r": 13666}, {"l": "hauptnenner", "t": "hauptnenner", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Zwei Pumpen füllen zusammen ein Becken in 4 Stunden. Pumpe B braucht allein doppelt so lange wie Pumpe A allein. Beide pumpen gleichmäßig und stören sich nicht. Wie viele Stunden braucht Pumpe A allein?"}, "o": {"wert": 6, "einheit": "Stunden"}, "h": "Pumpe A braucht x Stunden, Pumpe B 2x Stunden. In einer Stunde schafft A den Teil 1/x des Beckens und B den Teil 1/(2x). Zusammen schaffen sie in einer Stunde ein Viertel.", "w": "Gleichung: 1/x + 1/(2x) = 1/4. Beide Seiten mit 4x malnehmen: 4 + 2 = x. Also x = 6. Pumpe A braucht 6 Stunden, Pumpe B 12 Stunden. Probe: 1/6 + 1/12 = 2/12 + 1/12 = 3/12 = 1/4.", "form": "anwenden", "zaehlt": "ja", "r": 13667}, {"l": "hauptnenner", "t": "hauptnenner", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst 2/x + 3/(2x) = 7/4 (x ≠ 0). Zeile 1: Hauptnenner 2x: 2/x = 4/(2x). Zeile 2: Addieren: 4/(2x) + 3/(2x) = 7/(4x). Zeile 3: Also gilt 7/(4x) = 7/4 und damit x = 1. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wenn Brüche denselben Nenner haben: Was passiert mit dem Nenner beim Addieren?", "w": "Beim Addieren gleichnamiger Brüche werden nur die Zähler addiert, der Nenner bleibt: 4/(2x) + 3/(2x) = 7/(2x). Dann ist 7/(2x) = 7/4 und x = 2. Zeile 3 rechnet mit dem falschen Ergebnis der Zeile 2 richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13668}, {"l": "scheinloesung", "t": "scheinloesung", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Zeichnung zeigt die Graphen von y = x/(x − 2) und y = 2/(x − 2). Bei gleichem x ist der Abstand der Graphen die Differenz ihrer Funktionswerte. Welche Aussage über die Gleichung x/(x − 2) = 2/(x − 2) stimmt?", "grafik": {"typ": "koordinaten", "x": [-4, 8], "y": [-6, 8], "graphen": [{"art": "hyperbel", "a": 2, "b": -2, "c": 1, "name": "y = x/(x − 2)"}, {"art": "hyperbel", "a": 2, "b": -2, "c": 0, "name": "y = 2/(x − 2)"}]}}, "a": ["Die Gleichung hat genau eine Lösung, nämlich x = 2, denn dort laufen beide Graphen zusammen.", "Die Gleichung hat keine Lösung: Die Graphen haben keinen gemeinsamen Punkt, und die Zahl 2 ist nur eine Scheinlösung.", "Die Gleichung hat unendlich viele Lösungen, weil beide Brüche denselben Nenner haben."], "o": {"index": 1}, "h": "Haben die beiden Graphen einen gemeinsamen Punkt? Welche Zahl x ergibt sich beim Umformen, und darf man sie einsetzen?", "w": "Mit (x − 2) multipliziert bleibt x = 2. Für x = 2 ist der Nenner 0, die Zahl gehört nicht zur Definitionsmenge. Bei gleichem x ist der Abstand der Graphen die Differenz der Funktionswerte: x/(x − 2) − 2/(x − 2) = (x − 2)/(x − 2) = 1. Die Graphen liegen also immer 1 Einheit auseinander. Die Lösungsmenge ist leer.", "form": "bruecke", "zaehlt": "ja", "r": 13669}, {"l": "scheinloesung", "t": "scheinloesung", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Gegeben ist die Gleichung x²/(x − 3) = (x + 6)/(x − 3) mit Zahlen aus ℚ. Bestimme zuerst alle Kandidaten, die beim Umformen entstehen, und prüfe jeden in der Ausgangsgleichung. Welche Zahl x löst die Gleichung wirklich?"}, "o": {"wert": -2}, "h": "Was passiert mit dem Nenner der Ausgangsgleichung, wenn du einen Kandidaten einsetzt?", "w": "Mit (x − 3) multipliziert: x² = x + 6, also x² − x − 6 = 0 und (x − 3)(x + 2) = 0. Kandidaten: x = 3 und x = −2. Probe in der Ausgangsgleichung: Für x = 3 ist der Nenner 0, das ist eine Scheinlösung. Für x = −2 gilt 4/(−5) = 4/(−5), das stimmt. Die einzige Lösung ist x = −2.", "form": "anwenden", "zaehlt": "ja", "r": 13670}, {"l": "verhaeltnis", "t": "verhaeltnis", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Sirup und Wasser werden im Verhältnis 3 : 8 gemischt. Weg A: Verhältnisgleichung 3/8 = 4,5/x über Kreuz lösen. Weg B: den Faktor bestimmen, mit dem aus 3 die Zahl 4,5 wird, und 8 mit demselben Faktor malnehmen. Wie viel Liter Wasser gehören zu 4,5 Litern Sirup?"}, "o": {"wert": 12, "einheit": "Liter"}, "h": "Beide Wege müssen dieselbe Zahl ergeben. Bei Weg B rechnest du zuerst 4,5 : 3.", "w": "Weg A: 3x = 8 · 4,5 = 36, also x = 12. Weg B: 4,5 : 3 = 1,5; 8 · 1,5 = 12. Es sind 12 Liter Wasser. Probe: 3 : 8 = 4,5 : 12.", "form": "zwei_wege", "zaehlt": "ja", "r": 13671}, {"l": "verhaeltnis", "t": "verhaeltnis", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Zucker und Mehl werden für einen Teig im Verhältnis 2 : 7 gemischt. Kim berechnet, wie viel Gramm Mehl zu 8 g Zucker gehören. Zeile 1: Ansatz: Zucker durch Mehl, also 2/7 = 8/x. Zeile 2: Über Kreuz: 2x = 7 · 8, also 2x = 56. Zeile 3: Dann ist x = 56 · 2 = 112 g Mehl. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wie kommt man von 2x = 56 zu x? Mache die Probe: Passt 2 : 7 zu 8 : 112?", "w": "2x bedeutet 2 mal x. Man teilt beide Seiten durch 2: x = 56 : 2 = 28 g Mehl. Probe: 2 : 7 = 8 : 28.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13672}, {"l": "graphisch", "t": "graphisch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Rechteck hat den Flächeninhalt 12 cm². Eine Seite ist x cm lang (x > 0), die andere Seite ist 12/x cm lang. Die Seite 12/x ist 1 cm länger als die Seite x. Die Zeichnung zeigt die Graphen von y = 12/x und y = x + 1. Wie lang ist die Seite x in Zentimetern?", "grafik": {"typ": "koordinaten", "x": [-6, 6], "y": [-6, 8], "graphen": [{"art": "hyperbel", "a": 12, "b": 0, "c": 0, "name": "y = 12/x"}, {"art": "linear", "m": 1, "t": 1, "name": "y = x + 1"}]}}, "o": {"wert": 3, "einheit": "cm"}, "h": "Wo schneiden sich die beiden Graphen für x > 0? Lies die x-Koordinate des Schnittpunkts ab und prüfe mit dem Flächeninhalt.", "w": "Die Gleichung ist 12/x = x + 1. Die Graphen schneiden sich für x > 0 im Punkt (3 | 4). Also ist x = 3 cm und 12/x = 4 cm. Probe: 3 · 4 = 12 und 4 = 3 + 1. (Der zweite Schnittpunkt bei x = −4 passt wegen x > 0 nicht.)", "form": "anwenden", "zaehlt": "ja", "r": 13673}, {"l": "graphisch", "t": "graphisch", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Zeichnung zeigt die Gerade y = 2x − 2 und den markierten Schnittpunkt S mit der Hyperbel y = k/x. Lies die Koordinaten von S ab. Welche Zahl ist k?", "grafik": {"typ": "koordinaten", "x": [0, 6], "y": [0, 10], "graphen": [{"art": "linear", "m": 2, "t": -2}], "punkte": [{"x": 4, "y": 6}]}}, "o": {"wert": 24}, "h": "Welche Koordinaten hat S? Der Punkt liegt auch auf der Hyperbel: setze ihn in y = k/x ein.", "w": "Aus der Zeichnung: S = (4 | 6). Kontrolle mit der Geraden: 2 · 4 − 2 = 6. Der Punkt (4 | 6) liegt auch auf der Hyperbel: 6 = k/4. Also k = 24. Probe: 24/4 = 6.", "form": "umkehren", "zaehlt": "ja", "r": 13674}]$auf$::jsonb),
    (31, 'stochastik.grundbegriffe', 590, 6, $auf$[{"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Ein Glücksrad hat 8 gleich große Felder. Die Tabelle zeigt die Zahl auf jedem Feld. Ein Ergebnis ist das Feld, auf dem das Rad stehen bleibt. Wie viele Ergebnisse gehören zum Gegenereignis von „Die Zahl ist eine Primzahl“?", "grafik": {"typ": "tabelle", "kopf": ["Feld", "1", "2", "3", "4", "5", "6", "7", "8"], "zeilen": [["Zahl", "2", "3", "3", "5", "8", "8", "2", "7"]]}}, "o": {"wert": 2}, "h": "Zähle Felder, nicht Zahlen. Welche Felder gehören zum Ereignis selbst?", "w": "Zum Ereignis gehören die Felder 1, 2, 3, 4, 7 und 8 (Zahlen 2, 3, 3, 5, 2 und 7). Das sind 6 Ergebnisse. Das Gegenereignis enthält alle übrigen Ergebnisse: die Felder 5 und 6, beide mit der Zahl 8. Es hat 8 − 6 = 2 Ergebnisse.", "form": "bruecke", "zaehlt": "ja", "r": 13591}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Glücksrad hat 12 gleich große Felder mit den Zahlen 1 bis 12. Ein Ergebnis ist die Zahl, bei der das Rad stehen bleibt. Ereignis A: „Die Zahl ist durch 3 teilbar“. Ereignis B: „Die Zahl ist größer als 6“. Weg A: Die Zahlen von A und B aufschreiben und doppelte nur einmal zählen. Weg B: Die Anzahl der Zahlen von A und die von B zusammenzählen und die Anzahl der Zahlen abziehen, die in beiden Ereignissen stehen. Wie viele Ergebnisse gehören zum Ereignis „A oder B“ (A, B oder beides)?"}, "o": {"wert": 8}, "h": "Welche Zahlen stehen in A und in B zugleich? Sie dürfen nur einmal gezählt werden.", "w": "A hat die Zahlen 3, 6, 9, 12 (4 Ergebnisse). B hat die Zahlen 7, 8, 9, 10, 11, 12 (6 Ergebnisse). In beiden stehen 9 und 12. Weg A: 3, 6, 7, 8, 9, 10, 11, 12 sind 8 Zahlen. Weg B: 4 + 6 − 2 = 8. Probe: Das Gegenereignis hat die Zahlen 1, 2, 4, 5. Das sind 4 Zahlen, und 12 − 4 = 8.", "form": "zwei_wege", "zaehlt": "ja", "r": 13592}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Reißnagel wird 80-mal geworfen. 28-mal landet er mit der Spitze nach oben. Welche Rechnung gibt die relative Häufigkeit von „Spitze nach oben“ in Prozent?"}, "a": ["80 durch 28 teilen und das Ergebnis mit 100 malnehmen", "28 mit 80 malnehmen und durch 100 teilen", "die Differenz von 80 und 28 durch 80 teilen und das Ergebnis mit 100 malnehmen", "28 durch 80 teilen und das Ergebnis mit 100 malnehmen"], "o": {"index": 3}, "h": "Relative Häufigkeit ist ein Anteil. Wovon ist der Teil, und was ist das Ganze?", "w": "Der Teil sind 28 Würfe, das Ganze sind 80 Würfe. 28 : 80 = 0,35 und 0,35 · 100 = 35 Prozent. Die anderen Rechnungen geben ungefähr 286 Prozent, 22,4 und 65 Prozent.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 13593}, {"l": "rel_haeufigkeit", "t": "rel_haeufigkeit", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Würfel wird in einer ersten Serie mehrmals geworfen. Die Sechs fällt 15-mal, ihre relative Häufigkeit ist 20 Prozent. In einer zweiten Serie wird derselbe Würfel noch 25-mal geworfen, dabei fällt die Sechs wieder 15-mal. Wie groß ist die relative Häufigkeit der Sechs in beiden Serien zusammen (in Prozent)?"}, "o": {"wert": 30, "einheit": "%"}, "h": "Wie viele Würfe hatte die erste Serie? Zähle dann alle Sechsen und alle Würfe zusammen.", "w": "Erste Serie: 15 : n = 0,2, also n = 15 : 0,2 = 75 Würfe. Beide Serien: 75 + 25 = 100 Würfe und 15 + 15 = 30 Sechsen. Relative Häufigkeit: 30 : 100 = 0,3, das sind 30 Prozent. Probe: 20 Prozent von 75 sind 15.", "form": "umkehren", "zaehlt": "ja", "r": 13594}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Bei einem Spiel wird zuerst eine Münze geworfen. Fällt Zahl, ist das Spiel zu Ende. Fällt Wappen, wird danach ein Würfel mit den Zahlen 1 bis 6 geworfen. Das Spiel wird als Baumdiagramm gezeichnet. Wie viele Wege führen vom Start bis zu einem Ende?"}, "o": {"wert": 7}, "h": "Zeichne den Baum. Wie viele Wege gehen durch den Ast „Wappen“, wie viele durch den Ast „Zahl“?", "w": "Der Ast „Zahl“ endet sofort: 1 Weg. Der Ast „Wappen“ teilt sich in 6 Äste für den Würfel: 6 Wege. Zusammen sind es 1 + 6 = 7 Wege. Nicht 2 · 6, denn nach „Zahl“ wird nicht gewürfelt.", "form": "anwenden", "zaehlt": "ja", "r": 13595}, {"l": "darstellen", "t": "darstellen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim zieht zweimal hintereinander eine Kugel aus einer Urne mit den Kugeln 1, 2, 3 und 4. Die gezogene Kugel wird nicht zurückgelegt. Kim zeichnet das Baumdiagramm und zählt. Zeile 1: Beim ersten Zug gibt es 4 Möglichkeiten. Zeile 2: Die gezogene Kugel bleibt draußen. Beim zweiten Zug gibt es nur noch 3 Möglichkeiten. Zeile 3: Das Baumdiagramm hat 12 Wege, denn 4 mal 3 sind 12. Zeile 4: Zum Ereignis „Die Summe ist 6“ gehören die Wege (2 | 4), (4 | 2) und (3 | 3). Das sind 3 Wege. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Prüfe jede Zeile einzeln: Passt sie zu der Regel, dass die Kugel nicht zurückgelegt wird?", "w": "Zeile 1 bis 3 stimmen: 4 · 3 = 12 Wege. In Zeile 4 steht der Weg (3 | 3). Kugel 3 ist nach dem ersten Zug draußen und kann nicht noch einmal gezogen werden. Zur Summe 6 gehören nur (2 | 4) und (4 | 2), also 2 Wege. Die Summe 6 allein reicht nicht: Der Weg muss im Baum vorkommen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13596}]$auf$::jsonb),
    (34, 'terme.bruchterme', 666, 14, $auf$[{"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt einige Werte eines Bruchterms T(x). An der Stelle x = 1 ist T nicht definiert. Welcher Term passt zu allen Einträgen der Tabelle?", "grafik": {"typ": "tabelle", "kopf": ["x", "−1", "0", "1", "2", "3"], "zeilen": [["T(x)", "−3", "−6", "nicht definiert", "6", "3"]]}}, "a": ["6/(x + 1)", "6/x", "6/(x − 1)"], "o": {"index": 2}, "h": "An welcher Stelle wird der Nenner 0? Setze auch x = 2 ein und vergleiche mit der Tabelle.", "w": "Für 6/(x − 1) ist der Nenner bei x = 1 gleich 0, dort ist der Term nicht definiert. Die Werte: x = −1 ergibt 6/(−2) = −3, x = 0 ergibt −6, x = 2 ergibt 6, x = 3 ergibt 3. Das passt zur Tabelle.", "form": "bruecke", "zaehlt": "ja", "r": 13667}, {"l": "definitionsmenge", "t": "definitionsmenge", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim bestimmt die Definitionsmenge des Terms (x + 1)/(x² − 9) über ℚ. Zeile 1: Der Nenner darf nicht 0 sein: x² − 9 ≠ 0. Zeile 2: Aus x² = 9 folgt x = 3, also ist nur x = 3 verboten. Zeile 3: Die Definitionsmenge ist D = ℚ \\ {3}. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Zahlen ergeben beim Quadrieren 9? Probiere auch negative Zahlen.", "w": "Aus x² = 9 folgen zwei Zahlen: x = 3 und x = −3, denn auch (−3)² = 9. Beide machen den Nenner 0. Richtig: D = ℚ \\ {−3; 3}. Zeile 3 übernimmt nur die unvollständige Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13668}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Klasse mietet einen Bus. Der Bus kostet 360 € Grundpreis, dazu kommen 6 € Verpflegung je Person. Bei k Personen zahlt jede Person (360 + 6k)/k Euro (k ≥ 1). Wie viel Euro zahlt jede Person bei k = 40?"}, "o": {"wert": 15, "einheit": "€"}, "h": "Setze k = 40 im Zähler und im Nenner ein. Rechne den Zähler zuerst aus.", "w": "Zähler: 360 + 6 · 40 = 360 + 240 = 600. Nenner: 40. Dann 600 : 40 = 15. Jede Person zahlt 15 €. Probe: 9 € für den Bus plus 6 € Verpflegung.", "form": "anwenden", "zaehlt": "ja", "r": 13669}, {"l": "termwert", "t": "termwert", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Der Term T(x) = (x + k)/(x − 2) ist für x ≠ 2 definiert. Für welche Zahl k hat er an der Stelle x = 5 den Wert 3?"}, "o": {"wert": 4}, "h": "Rechne zuerst den Nenner an der Stelle x = 5 aus.", "w": "Der Nenner ist 5 − 2 = 3. Der Zähler muss 3 · 3 = 9 sein. Also 5 + k = 9 und k = 4. Probe: (5 + 4)/(5 − 2) = 9 : 3 = 3.", "form": "umkehren", "zaehlt": "ja", "r": 13670}, {"l": "kuerzen", "t": "kuerzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne den Wert von (x² − 25)/(x² + 5x) für x = 10 auf zwei Wegen (der Term ist für x ≠ 0 und x ≠ −5 definiert). Weg A: Zähler und Nenner in Faktoren zerlegen, kürzen und dann x = 10 einsetzen. Weg B: x = 10 sofort in Zähler und Nenner einsetzen und den Zahlenbruch ausrechnen. Welchen Wert hat der Term?"}, "o": {"wert": 0.5}, "h": "Beide Wege müssen denselben Wert liefern. Der Zähler ist (x − 5)(x + 5), der Nenner ist x(x + 5).", "w": "Weg A: Der Zähler ist (x − 5)(x + 5), der Nenner ist x(x + 5). Nach dem Kürzen mit x + 5 bleibt (x − 5)/x. Für x = 10 ist das 5/10 = 0,5. Weg B: Zähler 100 − 25 = 75, Nenner 100 + 50 = 150, und 75 : 150 = 0,5.", "form": "zwei_wege", "zaehlt": "ja", "r": 13671}, {"l": "kuerzen", "t": "kuerzen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein rechteckiges Grundstück hat den Flächeninhalt (x² − 16) m² und die Länge (x + 4) m (x > 4). Die Breite ist der Quotient aus Fläche und Länge. Wie breit ist das Grundstück in Metern für x = 60?"}, "o": {"wert": 56, "einheit": "m"}, "h": "Die Breite ist ein Quotient. Vereinfache ihn zuerst, bevor du x einsetzt.", "w": "x² − 16 = (x − 4)(x + 4). Breite = (x − 4)(x + 4)/(x + 4) = x − 4. Für x = 60 ist das 56 m. Probe: Fläche 3600 − 16 = 3584 m², Länge 64 m, 3584 : 64 = 56.", "form": "anwenden", "zaehlt": "ja", "r": 13672}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Der Bruchterm 4/(x − 2) wurde so erweitert, dass der neue Nenner x² − 4 ist (x ≠ 2 und x ≠ −2). Welchen Wert hat der neue Zähler für x = 5?"}, "o": {"wert": 28}, "h": "Womit musst du x − 2 malnehmen, um x² − 4 zu erhalten? Mit demselben Term wird auch der Zähler malgenommen.", "w": "x² − 4 = (x − 2)(x + 2). Es wurde mit x + 2 erweitert. Der neue Zähler ist 4(x + 2). Für x = 5: 4 · 7 = 28. Probe: 4/3 = 28/21.", "form": "umkehren", "zaehlt": "ja", "r": 13673}, {"l": "erweitern", "t": "erweitern", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim erweitert 2/(x − 1) so, dass der Nenner x² − 1 wird. Zeile 1: Es ist x² − 1 = (x − 1)(x + 1), erlaubt sind x ≠ 1 und x ≠ −1. Also wird mit x + 1 erweitert. Zeile 2: Der Zähler wird 2 · (x + 1) = 2x + 1. Zeile 3: Ergebnis: (2x + 1)/(x² − 1) mit x ≠ 1 und x ≠ −1. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechne 2 · (x + 1) einzeln aus. Wird jeder Summand malgenommen?", "w": "2 · (x + 1) = 2x + 2, nicht 2x + 1. Beim Erweitern müssen Zähler und Nenner mit demselben ganzen Term malgenommen werden. Richtig: (2x + 2)/(x² − 1). Zeile 3 übernimmt nur den Fehler der Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13674}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt einige Werte von T(x) = 1/x + 1/(x + 1) (x ≠ 0 und x ≠ −1). Welcher Bruchterm ist zu T(x) gleichwertig, und mit welcher Gegenprobe und Begründung ist das richtig belegt?", "grafik": {"typ": "tabelle", "kopf": ["x", "1", "2", "3", "4"], "zeilen": [["T(x)", "3/2", "5/6", "7/12", "9/20"]]}}, "a": ["(2x + 1)/(x² + x). Gegenprobe: x = 2 ergibt 5/6, das steht in der Tabelle. Begründung: Mit dem Hauptnenner x² + x wird aus 1/x der Bruch (x + 1)/(x² + x) und aus 1/(x + 1) der Bruch x/(x² + x), die Zähler addieren sich zu 2x + 1.", "(2x + 1)/(x² + x). Gegenprobe: x = 2 ergibt 5/6, das steht in der Tabelle. Begründung: Zähler und Nenner werden getrennt addiert, also (1 + 1)/(x + x + 1).", "2/(x² + x). Gegenprobe: x = 1 ergibt 1, das stimmt mit der Tabelle überein. Begründung: Mit dem Hauptnenner x² + x werden nur die Nenner malgenommen, die Zähler 1 + 1 ergeben 2."], "o": {"index": 0}, "h": "Setze x = 1 in jeden Term ein und vergleiche mit der Tabelle. Wie kommt man auf den Hauptnenner?", "w": "Hauptnenner x(x + 1) = x² + x: 1/x = (x + 1)/(x² + x) und 1/(x + 1) = x/(x² + x). Summe: (2x + 1)/(x² + x). Für x = 1: 3/2, für x = 2: 5/6, für x = 3: 7/12, für x = 4: 9/20. Die Tabelle widerlegt zum Beispiel 2/(x² + x): für x = 1 ergibt es 1 statt 3/2. Der Hauptnenner begründet den richtigen Term für alle x, die Tabelle prüft nur vier Werte.", "form": "bruecke", "zaehlt": "ja", "r": 13675}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl a gilt 1/x + a/(x + 2) = (3x + 2)/(x² + 2x) für alle Zahlen x mit x ≠ 0 und x ≠ −2?"}, "o": {"wert": 2}, "h": "Bringe die linke Seite auf den Nenner x² + 2x. Vergleiche dann die Zähler: die Zahl vor x und die Zahl ohne x.", "w": "Hauptnenner x(x + 2) = x² + 2x. 1/x = (x + 2)/(x² + 2x) und a/(x + 2) = ax/(x² + 2x). Zähler: (x + 2) + ax = (1 + a)x + 2. Das soll 3x + 2 sein, also 1 + a = 3 und a = 2.", "form": "umkehren", "zaehlt": "ja", "r": 13676}, {"l": "multiplizieren", "t": "multiplizieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne (x² − 4)/(x + 3) · (x + 3)/(x − 2) für x = 5 auf zwei Wegen (x ≠ −3 und x ≠ 2). Weg A: erst die Brüche multiplizieren, kürzen und vereinfachen, dann x = 5 einsetzen. Weg B: x = 5 sofort in beide Brüche einsetzen und die zwei Zahlenbrüche multiplizieren. Welchen Wert hat das Produkt?"}, "o": {"wert": 7}, "h": "Beide Wege müssen denselben Wert ergeben. Zerlege x² − 4 in zwei Faktoren.", "w": "Weg A: (x − 2)(x + 2)/(x + 3) · (x + 3)/(x − 2) = x + 2. Für x = 5 ist das 7. Weg B: 21/8 · 8/3 = 168/24 = 7.", "form": "zwei_wege", "zaehlt": "ja", "r": 13677}, {"l": "multiplizieren", "t": "multiplizieren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Das Produkt 4x/(x − 2) · (x − 2)/(a · x²) soll für alle Zahlen x mit x ≠ 0 und x ≠ 2 gleich 2/x sein (a ≠ 0). Welche Zahl a ist das?"}, "o": {"wert": 2}, "h": "Kürze gemeinsame, von null verschiedene Faktoren. Vergleiche dann den Rest mit 2/x.", "w": "Im Produkt kürzt sich x − 2 weg, und ein x kürzt sich auch. Es bleibt der Bruch 4/(a · x). Das soll 2/x sein, also 4/a = 2 und a = 2. Probe: 4x/(2x²) = 2/x.", "form": "umkehren", "zaehlt": "ja", "r": 13678}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Kim behauptet: Es gilt (x + 6)/(x + 2) = 3 für alle Zahlen x ≠ −2. Die Tabelle zeigt beide Seiten für einige Zahlen x. Was folgt aus der Tabelle?", "grafik": {"typ": "tabelle", "kopf": ["x", "0", "1", "2", "4"], "zeilen": [["(x + 6)/(x + 2)", "3", "7/3", "2", "5/3"], ["rechte Seite 3", "3", "3", "3", "3"]]}}, "a": ["Die Behauptung ist richtig, denn für x = 0 stimmen beide Seiten überein.", "Die Behauptung ist falsch: Zum Beispiel für x = 2 ist der linke Wert 2 und nicht 3.", "Die Behauptung ist falsch, denn für x = 0 sind beide Seiten verschieden."], "o": {"index": 1}, "h": "Eine Behauptung „für alle x“ ist schon falsch, wenn sie für eine einzige Zahl nicht stimmt. Suche eine solche Zahl in der Tabelle.", "w": "Für x = 0 ist (0 + 6)/(0 + 2) = 3, die Seiten sind gleich. Für x = 2 ist 8/4 = 2, nicht 3. Ein einziges Gegenbeispiel genügt, um „für alle x“ zu widerlegen. Gekürzt werden darf nicht aus einer Summe.", "form": "bruecke", "zaehlt": "ja", "r": 13679}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Kim kürzt falsch und behauptet (x² + 9)/(x + 3) = x + 3. Die Behauptung ist für fast alle Zahlen falsch, aber für genau eine Zahl x ≠ −3 stimmt sie zufällig. Für welche Zahl?"}, "o": {"wert": 0}, "h": "Für welche Zahlen x sind beide Seiten gleich?", "w": "(x² + 9)/(x + 3) = x + 3 bedeutet x² + 9 = (x + 3)² = x² + 6x + 9. Dann 6x = 0, also x = 0. Probe: 9/3 = 3 und 0 + 3 = 3. Für alle anderen Zahlen x ≠ −3 ist die Behauptung falsch, zum Beispiel für x = 1: 10/4 ist nicht 4.", "form": "umkehren", "zaehlt": "ja", "r": 13680}]$auf$::jsonb),
    (72, 'terme.quadratische_extreme', 390, 10, $auf$[{"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Quadrat hat die Seitenlänge x m. An zwei benachbarten Seiten wird je ein Streifen der Breite 3 m angelegt. Quadrat und beide Streifen haben zusammen die Fläche x² + 6x. An der Ecke fehlt noch ein kleines Quadrat, damit ein großes Quadrat entsteht. Wie lang ist die Seite des großen Quadrats in Metern, wenn x = 7 ist?"}, "o": {"wert": 10, "einheit": "m"}, "h": "Das große Quadrat besteht aus dem Quadrat mit Seite x, zwei Streifen und dem kleinen Eckquadrat. Welche Länge hat jede Seite des großen Quadrats?", "w": "Das kleine Eckquadrat hat die Seitenlänge 3 m und die Fläche 9 m². Das große Quadrat hat die Fläche x² + 6x + 9 = (x + 3)². Seine Seite ist x + 3. Für x = 7 ist das 10 m.", "form": "anwenden", "zaehlt": "ja", "r": 13391}, {"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Funktion f(x) = x² + 8x + 5 soll in die Form (x + a)² + b gebracht werden. Weg A: quadratische Ergänzung. Weg B: (x + a)² + b ausmultiplizieren und die Zahlen vor x sowie die Zahlen ohne x vergleichen. Welche Zahl ist b?"}, "o": {"wert": -11}, "h": "Beide Wege müssen dieselbe Zahl b ergeben. Aus der Zahl vor x erhältst du zuerst a.", "w": "Weg A: x² + 8x + 16 − 16 + 5 = (x + 4)² − 11. Weg B: (x + a)² + b = x² + 2ax + a² + b. Aus 2a = 8 folgt a = 4. Aus a² + b = 5 folgt 16 + b = 5, also b = −11. Probe: (x + 4)² − 11 = x² + 8x + 5.", "form": "zwei_wege", "zaehlt": "ja", "r": 13392}, {"l": "scheitelform", "t": "scheitelform", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Springbrunnenstrahl verläuft auf der Parabel h(x) = −0,5·(x − 3)² + 4,5 (x ist der waagerechte Abstand von der Düse in Metern, h die Höhe in Metern). Um wie viele Meter liegt der höchste Punkt des Strahls höher als der Strahl bei x = 1?"}, "o": {"wert": 2, "einheit": "m"}, "h": "Lies aus der Scheitelform die größte Höhe ab. Berechne dann h(1).", "w": "Der Scheitel liegt bei (3 | 4,5): Der Strahl ist höchstens 4,5 m hoch. h(1) = −0,5 · (−2)² + 4,5 = −2 + 4,5 = 2,5. Unterschied: 4,5 − 2,5 = 2 m.", "form": "anwenden", "zaehlt": "ja", "r": 13393}, {"l": "scheitelform", "t": "scheitelform", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Parabel y = a·(x − 2)² + 1 geht durch den Punkt P(4 | 9). Welche Zahl ist a?"}, "o": {"wert": 2}, "h": "Der Punkt P liegt auf der Parabel.", "w": "Aus 9 = a · (4 − 2)² + 1 folgt 9 = 4a + 1, also 4a = 8 und a = 2. Probe: y = 2(x − 2)² + 1 gibt für x = 4 den Wert 2 · 4 + 1 = 9.", "form": "umkehren", "zaehlt": "ja", "r": 13394}, {"l": "extremwert", "t": "extremwert", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Zeichnung zeigt die beiden Nullstellen der Funktion f(x) = x² + bx + c. Welchen kleinsten Funktionswert hat f für alle reellen Zahlen x?", "grafik": {"typ": "koordinaten", "x": [-1, 7], "y": [-1, 3], "punkte": [{"x": 1, "y": 0, "name": "N1"}, {"x": 5, "y": 0, "name": "N2"}]}}, "o": {"wert": -4}, "h": "Der Scheitel einer Parabel liegt auf ihrer Symmetrieachse.", "w": "Die Parabel ist nach oben geöffnet und hat die Form f(x) = (x − 1)(x − 5). Der Scheitel liegt in der Mitte der beiden Nullstellen, also bei x = 3. Dort ist f(3) = 2 · (−2) = −4. Probe: f(x) = x² − 6x + 5 gibt f(3) = 9 − 18 + 5 = −4.", "form": "bruecke", "zaehlt": "ja", "r": 13395}, {"l": "extremwert", "t": "extremwert", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim sucht den größten Wert von g(x) = −x² + 6x − 2 für alle reellen Zahlen x. Zeile 1: Ausklammern von −1 bei den ersten beiden Gliedern: g(x) = −(x² − 6x) − 2. Zeile 2: Ergänzen mit 9 und −9: g(x) = −((x − 3)² − 9) − 2. Zeile 3: Zusammengefasst: g(x) = −(x − 3)² + 7. Zeile 4: Der größte Wert ist 7. Er wird bei x = 7 angenommen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Wo ist (x − 3)² gleich null? Setze diese Stelle in g ein.", "w": "Der größte Wert 7 stimmt. Aber (x − 3)² ist null bei x = 3 und nicht bei x = 7. Probe: g(3) = −9 + 18 − 2 = 7, aber g(7) = −49 + 42 − 2 = −9. Der größte Wert 7 wird bei x = 3 angenommen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13396}, {"l": "mit_faktor", "t": "mit_faktor", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Funktion f(x) = a·x² − 12x + 5 mit a ≠ 0 hat ihren Scheitel bei x = 3. Für eine Funktion f(x) = ax² + bx + c liegt die Scheitelstelle bei x = −b/(2a). Welche Zahl ist a?"}, "o": {"wert": 2}, "h": "Welche Zahl ist hier b? Setze b und die Scheitelstelle 3 in x = −b/(2a) ein.", "w": "Hier ist b = −12, also x = 12/(2a) = 6/a. Aus 6/a = 3 folgt a = 2. Dieselbe Stelle ergibt die quadratische Ergänzung: f(x) = a(x² − (12/a)·x) + 5. Die Klammer wird zu (x − 6/a)² − 36/a². Der Scheitel liegt bei x = 6/a. Probe: f(x) = 2x² − 12x + 5 = 2(x − 3)² − 13, der Scheitel liegt bei x = 3.", "form": "umkehren", "zaehlt": "ja", "r": 13397}, {"l": "mit_faktor", "t": "mit_faktor", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Laden verkauft einen Artikel zum Preis p (in Euro). Der Gewinn pro Tag beträgt G(p) = −2p² + 20p − 30 Euro. Dieses Modell gilt nur für Preise mit 3 ≤ p ≤ 4. Wie groß ist der größte Gewinn pro Tag in Euro, den der Laden mit einem Preis aus diesem Bereich erreichen kann?"}, "o": {"wert": 18, "einheit": "€"}, "h": "Beachte, welche Preise erlaubt sind.", "w": "G(p) = −2(p − 5)² + 20. Der größte Wert der ganzen Parabel liegt bei p = 5, aber der Preis darf nur zwischen 3 und 4 liegen. In diesem Bereich wächst G, denn der Scheitel liegt weiter rechts. Der größte Gewinn ist bei p = 4: G(4) = −32 + 80 − 30 = 18.", "form": "anwenden", "zaehlt": "ja", "r": 13398}, {"l": "optimierung", "t": "optimierung", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Mit einem Zaun der Länge L wird ein Rechteck vollständig umzäunt. Der ganze Zaun wird verbaut. Bei festem Umfang hat das Quadrat die größte Fläche. Die größte Fläche, die man so umzäunen kann, ist 100 m². Wie lang ist der Zaun in Metern?"}, "o": {"wert": 40, "einheit": "m"}, "h": "Welche Form hat das Rechteck mit der größten Fläche? Wie hängt dann die Seitenlänge mit L zusammen?", "w": "Das beste Rechteck ist ein Quadrat mit Seite s, die Fläche ist s² = 100, also s = 10 und L = 4 · 10 = 40. Dasselbe zeigt die Rechnung: Die andere Seite ist L/2 − b. Die Fläche ist A(b) = b(L/2 − b). Ihr größter Wert liegt in der Mitte der Nullstellen 0 und L/2, bei b = L/4. Dort ist A = (L/4)² = L²/16. Aus L²/16 = 100 folgt L² = 1600 und L = 40 (L > 0). Probe: Quadrat mit Seite 10 hat Umfang 40 und Fläche 100.", "form": "umkehren", "zaehlt": "ja", "r": 13399}, {"l": "optimierung", "t": "optimierung", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Landwirt zäunt an einer langen Mauer ein Rechteck ab. Die Mauer ist eine Seite. Für die drei anderen Seiten hat er 40 m Zaun, der ganz verbaut wird. Weg A: Funktion der Fläche in Scheitelform umschreiben. Weg B: Nullstellen der Funktion bestimmen und die Symmetrie der Parabel nutzen. Wie groß ist die größte Fläche in Quadratmetern?"}, "o": {"wert": 200, "einheit": "m²"}, "h": "Die Seite senkrecht zur Mauer sei b. Wie lang ist dann die Seite parallel zur Mauer?", "w": "Die Seite parallel zur Mauer ist 40 − 2b lang. Fläche: A(b) = b(40 − 2b) = −2b² + 40b. Weg A: A(b) = −2(b − 10)² + 200, der größte Wert ist 200. Weg B: A(b) = 0 für b = 0 und b = 20. Der Scheitel liegt in der Mitte, bei b = 10, und dort ist A = 10 · 20 = 200. Beide Wege geben 200 m².", "form": "zwei_wege", "zaehlt": "ja", "r": 13400}]$auf$::jsonb),
    (305, 'terme.umformen_teil2', 789, 8, $auf$[{"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratischer Spielplatz hat die Seitenlänge x m. Er wird in der einen Richtung um 3 m und in der anderen Richtung um 2 m erweitert, sodass ein Rechteck entsteht. Um wie viele Quadratmeter wächst die Fläche, wenn x = 20 ist?"}, "o": {"wert": 106, "einheit": "m²"}, "h": "Die neue Fläche ist Länge mal Breite des Rechtecks. Ziehe die alte Fläche ab. Jeder Summand der ersten Klammer wird mit jedem der zweiten malgenommen.", "w": "Neue Fläche: (x + 3)(x + 2) = x² + 2x + 3x + 6 = x² + 5x + 6. Zuwachs: x² + 5x + 6 − x² = 5x + 6. Für x = 20: 100 + 6 = 106 m². Probe: 23 · 22 = 506, 506 − 400 = 106.", "form": "anwenden", "zaehlt": "ja", "r": 13790}, {"l": "summe_mal_summe", "t": "summe_mal_summe", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für zwei ganze Zahlen a und b mit 0 < a < b gilt (x + a)(x + b) = x² + 7x + 12 für alle Zahlen x. Wie groß ist a?"}, "o": {"wert": 3}, "h": "Multipliziere (x + a)(x + b) aus und vergleiche mit der rechten Seite. Was muss für a und b gelten?", "w": "(x + a)(x + b) = x² + (a + b)x + ab. Also gilt a + b = 7 und ab = 12. Mit 0 < a < b passt nur a = 3 und b = 4. Probe: (x + 3)(x + 4) = x² + 7x + 12.", "form": "umkehren", "zaehlt": "ja", "r": 13791}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Das Rechteck in der Zeichnung ist in zwei Teile geteilt. Die Höhe ist 5 cm. Die Breite des linken Teils ist x cm, die des rechten Teils 4 cm. Welcher Term gibt den Flächeninhalt des ganzen Rechtecks in cm² als Produkt an (Breite mal Höhe)?", "grafik": {"typ": "figur", "punkte": {"A": [0, 0], "B": [9, 0], "C": [9, 5], "D": [0, 5], "E": [5, 0], "F": [5, 5]}, "flaeche": ["A", "B", "C", "D"], "linien": [["A", "E", "x cm"], ["E", "B", "4 cm"], ["B", "C", "5 cm"], ["E", "F", "", "gestrichelt"]]}}, "a": ["5(x + 4)", "4(x + 5)", "x(5 + 4)"], "o": {"index": 0}, "h": "Wie breit ist das ganze Rechteck? Setze zur Probe x = 1 ein und rechne die Teilflächen einzeln aus.", "w": "Gesamtbreite: x + 4. Höhe: 5. Fläche: 5(x + 4) = 5x + 20, das ist die Summe der Teilflächen 5x und 20. Die anderen Terme ergeben 4x + 20 und 9x.", "form": "bruecke", "zaehlt": "ja", "r": 13792}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim klammert in 8a²b + 12ab² den größten gemeinsamen Faktor aus. Zeile 1: Der größte gemeinsame Teiler von 8 und 12 ist 4. Beide Glieder enthalten a und b. Ausgeklammert wird 4ab. Zeile 2: Jedes Glied wird in 4ab mal Rest zerlegt: 8a²b = 4ab · 2 und 12ab² = 4ab · 3. Zeile 3: Also gilt 8a²b + 12ab² = 4ab(2 + 3) = 20ab. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Multipliziere 4ab · 2 aus. Kommt 8a²b heraus? Prüfe so jedes Glied.", "w": "Aus den Potenzen: 8a²b = 4ab · 2a und 12ab² = 4ab · 3b. Richtig: 8a²b + 12ab² = 4ab(2a + 3b). Das Ausmultiplizieren bestätigt es: 4ab · 2a + 4ab · 3b = 8a²b + 12ab². In Zeile 2 sind die Buchstaben verloren gegangen, Zeile 3 rechnet damit nur weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13793}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 47² auf zwei Wegen. Weg A: 47 · (40 + 7) mit dem Verteilungsgesetz. Weg B: (50 − 3)² mit der zweiten binomischen Formel. Welchen Wert hat 47²?"}, "o": {"wert": 2209}, "h": "Beide Wege müssen dasselbe Ergebnis haben. Die zweite binomische Formel hat in der Mitte einen eigenen Summanden.", "w": "Weg A: 47 · 40 + 47 · 7 = 1 880 + 329 = 2 209. Weg B: (50 − 3)² = 50² − 2 · 50 · 3 + 3² = 2 500 − 300 + 9 = 2 209. Beide Wege führen auf 2 209.", "form": "zwei_wege", "zaehlt": "ja", "r": 13794}, {"l": "binomisch", "t": "binomisch", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim multipliziert (3x − 5)² mit der zweiten binomischen Formel aus. Zeile 1: Setze a = 3x und b = 5. Dann ist a² = 3x². Zeile 2: Das doppelte Produkt ist 2ab = 2 · 3x · 5 = 30x, und es ist b² = 25. Zeile 3: Also gilt (3x − 5)² = 3x² − 30x + 25. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Setze x = 1 ein: Was ergibt (3 · 1)²?", "w": "Das Quadrat von 3x ist (3x)² = 9x², denn auch die 3 wird quadriert. Richtig: (3x − 5)² = 9x² − 30x + 25. Zeile 2 ist richtig, Zeile 3 übernimmt nur den Fehler der Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13795}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Ein Quadrat hat die Seitenlänge x cm. Verlängert man jede Seite um 4 cm, so wird die Fläche um 56 cm² größer. Wie groß ist x in Zentimetern?"}, "o": {"wert": 5, "einheit": "cm"}, "h": "Die neue Fläche ist (x + 4)². Sie ist um 56 cm² größer als x². Schreibe das als Gleichung und multipliziere die Klammer aus.", "w": "Neue Seitenlänge x + 4, neue Fläche (x + 4)². Sie ist um 56 größer als die alte Fläche x². Gleichung: (x + 4)² = x² + 56. Ausmultipliziert: x² + 8x + 16 = x² + 56, also 8x = 40 und x = 5. Probe: 81 = 25 + 56.", "form": "bruecke", "zaehlt": "ja", "r": 13796}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Löse (2x + 5)² − (2x − 3)² = 80 auf zwei Wegen. Weg A: beide Klammern ausmultiplizieren. Weg B: die Differenz zweier Quadrate als Produkt (a + b)(a − b) schreiben, mit a = 2x + 5 und b = 2x − 3. Welche Zahl ist die Lösung x?"}, "o": {"wert": 2}, "h": "Bei beiden Wegen verschwindet x² und es bleibt eine Gleichung mit x. Setze zur Probe in die Ausgangsgleichung ein.", "w": "Weg A: 4x² + 20x + 25 − 4x² + 12x − 9 = 32x + 16 = 80, also x = 2. Weg B: a + b = 4x + 2 und a − b = 8. Dann 8(4x + 2) = 80, also 4x + 2 = 10 und x = 2. Probe: 9² − 1² = 81 − 1 = 80.", "form": "zwei_wege", "zaehlt": "ja", "r": 13797}]$auf$::jsonb),
    (306, 'geometrie.konstruktion_teil2', 632, 4, $auf$[{"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "In der Zeichnung ist ein Parallelogramm ABCD mit zwei Winkelangaben (in Grad) zu sehen. Benachbarte Winkel im Parallelogramm ergänzen sich zu 180°. Welche Zahl ist x?", "grafik": {"typ": "figur", "punkte": {"A": [0, 0], "B": [6, 0], "C": [8, 5.5], "D": [2, 5.5]}, "flaeche": ["A", "B", "C", "D"], "winkel": [["A", "B", "D", "(x + 30)°"], ["B", "C", "A", "(2x + 30)°"]]}}, "o": {"wert": 40}, "h": "Liegen die Ecken A und B nebeneinander oder gegenüber? Was gilt dann für die beiden Winkel?", "w": "A und B sind benachbarte Ecken. Benachbarte Winkel ergeben zusammen 180°: (x + 30) + (2x + 30) = 180. Also 3x + 60 = 180, 3x = 120 und x = 40. Probe: 70° + 110° = 180°.", "form": "bruecke", "zaehlt": "ja", "r": 13633}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "ABCD ist eine Raute: Alle vier Seiten sind gleich lang. Der Winkel bei A ist α = 50°. Weg A: Die Diagonale halbiert den Winkel der Raute. Weg B: Das Dreieck ABC ist gleichschenklig mit AB = BC. Der Winkel β bei B ist der Nachbarwinkel von α. Rechne den Basiswinkel bei A aus. Wie groß ist der Winkel zwischen der Seite AB und der Diagonale AC?"}, "o": {"wert": 25, "einheit": "°"}, "h": "Wie groß ist der Winkel β bei B? Nachbarwinkel im Parallelogramm ergänzen sich.", "w": "Weg A: Die Diagonale AC halbiert den Winkel bei A. 50° : 2 = 25°. Weg B: β = 180° − 50° = 130°. Im gleichschenkligen Dreieck ABC sind die Winkel bei A und bei C gleich groß: (180° − 130°) : 2 = 25°. Beide Wege geben 25°.", "form": "zwei_wege", "zaehlt": "ja", "r": 13634}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Du konstruierst ein Parallelogramm ABCD mit a = AB = 7 cm und α = 60°. Der Umfang soll 24 cm betragen. Gegenüberliegende Seiten sind gleich lang. Du hast AB gezeichnet und in A den Strahl für den Winkel 60° angetragen. Wie geht die Konstruktion richtig weiter?"}, "a": ["Auf dem Strahl von A aus AD = 10 cm abtragen. Durch D die Parallele zu AB und durch B die Parallele zu AD zeichnen. Ihr Schnittpunkt ist C.", "Auf dem Strahl von A aus AD = 5 cm abtragen. Durch D und durch B jeweils die Senkrechte zu AB zeichnen. Ihr Schnittpunkt ist C.", "Auf dem Strahl von A aus AD = 8,5 cm abtragen. Durch D die Parallele zu BD und durch B die Parallele zu AB zeichnen. Ihr Schnittpunkt ist C.", "Auf dem Strahl von A aus AD = 5 cm abtragen. Durch D die Parallele zu AB und durch B die Parallele zu AD zeichnen. Ihr Schnittpunkt ist C."], "o": {"index": 3}, "h": "Wie viele Seiten haben die Länge a und wie viele die Länge b? Welche Seiten sind zueinander parallel?", "w": "Der Umfang ist 2a + 2b = 24. Mit a = 7 ist 14 + 2b = 24, also b = 5. Probe: 2 · 7 + 2 · 5 = 24. Der Winkel 60° ändert den Umfang nicht. D liegt auf dem Strahl im Abstand 5 cm von A. In einem Parallelogramm ist DC parallel zu AB und BC parallel zu AD, deshalb ist C der Schnittpunkt der Parallele durch D zu AB und der Parallele durch B zu AD.", "form": "umkehren", "zaehlt": "ja", "r": 13635}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "auswahl", "f": {"text": "Ein Fliesenleger konstruiert eine Raute ABCD aus nur zwei Angaben: der Seitenlänge 9 cm und dem Winkel α = 60° bei A. Er zeichnet AB = 9 cm und trägt in A den Strahl für den Winkel 60° an. Danach schneidet er die Raute entlang der Diagonale BD in zwei Dreiecke. In einer Raute sind alle vier Seiten gleich lang. Welche Konstruktion und welcher Rand eines der beiden Dreiecke gehören zusammen?"}, "a": ["AD = 9 cm auf dem Strahl abtragen; durch D die Parallele zu AB und durch B die Parallele zu AD zeichnen, Schnittpunkt C. — Rand des Dreiecks ABD: 27 cm (das Dreieck ist gleichseitig).", "AD = 9 cm auf dem Strahl abtragen; durch D und durch B die Senkrechte zu AB zeichnen, Schnittpunkt C. — Rand des Dreiecks ABD: 27 cm (das Dreieck ist gleichseitig).", "AD = 9 cm auf dem Strahl abtragen; durch D die Parallele zu AB und durch B die Parallele zu AD zeichnen, Schnittpunkt C. — Rand des Dreiecks ABD: 18 cm.", "AD = 4,5 cm auf dem Strahl abtragen; durch D die Parallele zu AB und durch B die Parallele zu AD zeichnen, Schnittpunkt C. — Rand des Dreiecks ABD: 22,5 cm."], "o": {"index": 0}, "h": "Welche Länge hat AD, weil in der Raute alle Seiten gleich lang sind? Welche zwei Seiten und welcher Winkel gehören zum Dreieck ABD?", "w": "In der Raute ist AD = AB = 9 cm. Die Parallelen durch D und durch B legen C fest, dann ist auch BC = CD = 9 cm. Im Dreieck ABD ist AB = AD = 9 cm und der Winkel bei A ist 60°. Die beiden anderen Winkel sind gleich groß: (180° − 60°) : 2 = 60°. Das Dreieck ist gleichseitig, BD = 9 cm. Der Rand ist 9 + 9 + 9 = 27 cm lang. Senkrechte statt Parallelen ergäben keine Raute.", "form": "anwenden", "zaehlt": "ja", "r": 13636}]$auf$::jsonb),
    (308, 'abbildungen.kongruenz_teil3', 751, 6, $auf$[{"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "In der Zeichnung sind der Punkt P und das Zentrum Z eingetragen. P wird am Punkt Z gespiegelt. Welche Koordinaten hat der Bildpunkt P′?", "grafik": {"typ": "koordinaten", "x": [-3, 7], "y": [-1, 7], "punkte": [{"x": -1, "y": 1, "name": "P"}, {"x": 2, "y": 3, "name": "Z"}]}}, "a": ["P′(2 | 3)", "P′(5 | 5)", "P′(5 | 1)", "P′(3 | 2)"], "o": {"index": 1}, "h": "Lies zuerst die Koordinaten von P und Z ab. Wie viele Schritte geht man von P nach Z in x- und in y-Richtung?", "w": "P hat die Koordinaten (−1 | 1), Z hat (2 | 3). Von P nach Z sind es 3 Schritte nach rechts und 2 nach oben. Derselbe Weg noch einmal von Z aus führt zu (2 + 3 | 3 + 2) = (5 | 5). Z ist die Mitte der Strecke von P bis P′.", "form": "bruecke", "zaehlt": "ja", "r": 13752}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Der Punkt P(−4 | 3) wird am Punkt Z(1 | −3) gespiegelt. Weg A: Gehe den Weg von P nach Z noch einmal von Z aus. Weg B: Z ist die Mitte der Strecke von P bis P′. Rechne jede Koordinate von P′ aus den Koordinaten von P und Z. Wie groß ist die Summe der beiden Koordinaten des Bildpunkts P′?"}, "o": {"wert": -3}, "h": "Wie groß ist der Schritt von P nach Z in x-Richtung und wie groß in y-Richtung?", "w": "Weg A: Von P nach Z sind es 5 Schritte nach rechts und 6 nach unten. Von Z aus noch einmal: P′(1 + 5 | −3 − 6) = (6 | −9). Weg B: Z ist die Mitte, also ist x von Z gleich (−4 + x′) : 2. Daraus folgt x′ = 2 · 1 + 4 = 6 und genauso y′ = 2 · (−3) − 3 = −9. Beide Wege geben P′(6 | −9). Die Summe der Koordinaten ist 6 + (−9) = −3.", "form": "zwei_wege", "zaehlt": "ja", "r": 13753}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Der Punkt P wird um den Ursprung O(0 | 0) um 90° gegen den Uhrzeigersinn gedreht. Dabei wird aus (x | y) der Punkt (−y | x). Das Bild ist P′(−3 | 8). Wie groß ist die Summe der beiden Koordinaten von P?"}, "o": {"wert": 11}, "h": "Welche Koordinate von P wird zur ersten Koordinate von P′? Welche zur zweiten?", "w": "Aus P(x | y) wird P′(−y | x). Also ist −y = −3 und x = 8. Daraus folgt y = 3 und P(8 | 3). Probe: (x | y) = (8 | 3) wird zu (−3 | 8). Summe der Koordinaten von P: 8 + 3 = 11.", "form": "umkehren", "zaehlt": "ja", "r": 13754}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Der Punkt P(6 | 2) wird um Z(2 | −1) um 180° gedreht. Weg A: Der Vektor von Z nach P wird zweimal um 90° gegen den Uhrzeigersinn gedreht (aus (a | b) wird (−b | a)), dann wird er an Z angesetzt. Weg B: Z ist die Mitte der Strecke von P bis P′. Rechne jede Koordinate von P′ aus den Koordinaten von P und Z. Wie groß ist die Summe der beiden Koordinaten von P′?"}, "o": {"wert": -6}, "h": "Wie lautet der Vektor von Z nach P?", "w": "Weg A: Der Vektor von Z nach P ist (4 | 3). Nach 90° ist er (−3 | 4), nach nochmals 90° ist er (−4 | −3). Dann ist P′(2 − 4 | −1 − 3) = (−2 | −4). Weg B: x′ = 2 · 2 − 6 = −2 und y′ = 2 · (−1) − 2 = −4. Beide Wege geben P′(−2 | −4). Summe: −6.", "form": "zwei_wege", "zaehlt": "ja", "r": 13755}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "In der Zeichnung sind die Punkte A und B eingetragen. Der Vektor von A nach B wird um 90° gegen den Uhrzeigersinn gedreht. Dabei wird aus (x | y) der Vektor (−y | x). Welcher Vektor entsteht?", "grafik": {"typ": "koordinaten", "x": [-1, 6], "y": [-1, 6], "punkte": [{"x": 1, "y": 1, "name": "A"}, {"x": 4, "y": 3, "name": "B"}]}}, "a": ["(2 | −3)", "(−2 | 3)", "(−3 | 2)", "(−3 | −2)"], "o": {"index": 1}, "h": "Lies die Koordinaten von A und B ab. Wie lautet der Vektor von A nach B?", "w": "A(1 | 1) und B(4 | 3): Der Vektor von A nach B ist (4 − 1 | 3 − 1) = (3 | 2). Mit der Regel wird aus (x | y) der Vektor (−y | x), also (−2 | 3).", "form": "bruecke", "zaehlt": "ja", "r": 13756}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Roboter fährt auf einer Karte von oben gesehen (x zeigt nach Osten, y nach Norden). Er startet im Ursprung und fährt den Vektor (3 | 4). Dort dreht er sich um 90° nach links, also gegen den Uhrzeigersinn. Er fährt eine zweite Strecke, die genauso lang ist wie die erste. Der Vektor der zweiten Fahrt entsteht aus dem Vektor der ersten Fahrt durch diese Drehung. Eine x-Koordinate mit Minus liegt westlich vom Start. Welche x-Koordinate hat der Roboter am Ende?"}, "o": {"wert": -1}, "h": "Welchen Vektor hat die zweite Fahrt?", "w": "Der Vektor der ersten Fahrt ist (3 | 4). Nach einer Linksdrehung um 90° ist er (−4 | 3). Der Roboter steht am Ende bei (3 − 4 | 4 + 3) = (−1 | 7). Die x-Koordinate ist −1.", "form": "anwenden", "zaehlt": "ja", "r": 13757}]$auf$::jsonb),
    (310, 'raum.schraegbilder_teil2', 582, 8, $auf$[{"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Ein Quader hat vier Ecken mit den Koordinaten aus der Tabelle. A liegt im Ursprung. B, D und E sind die drei Nachbarecken von A. Die Kanten des Quaders verlaufen parallel zu den Achsen. Wie viele Volumeneinheiten hat der Quader?", "grafik": {"typ": "tabelle", "kopf": ["Ecke", "A", "B", "D", "E"], "zeilen": [["Koordinaten", "(0 | 0 | 0)", "(6 | 0 | 0)", "(0 | 4 | 0)", "(0 | 0 | 3)"]]}}, "o": {"wert": 72}, "h": "Welche Länge hat die Kante AB, welche AD und welche AE?", "w": "Die Kanten von A aus sind AB = 6 (x-Richtung), AD = 4 (y-Richtung) und AE = 3 (z-Richtung). Volumen = Länge mal Breite mal Höhe = 6 · 4 · 3 = 72 Volumeneinheiten.", "form": "bruecke", "zaehlt": "ja", "r": 13583}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Ein Quader hat die Ecken A(0 | 0 | 0), C(6 | 4 | 0), E(0 | 0 | 3) und G(6 | 4 | 3). Seine Kanten verlaufen parallel zu den Achsen. Grundfläche ist ABCD, Deckfläche ist EFGH, E liegt über A und G liegt über C. M ist der Mittelpunkt der Deckfläche. Weg A: M ist die Mitte der Strecke von E nach G. Weg B: M liegt senkrecht über dem Mittelpunkt N der Grundfläche ABCD. Wie groß ist die Summe der drei Koordinaten von M?"}, "o": {"wert": 8}, "h": "Welche Koordinate ändert sich zwischen E und G nicht?", "w": "Weg A: Mitte von E(0 | 0 | 3) und G(6 | 4 | 3): M(3 | 2 | 3). Weg B: N ist die Mitte von A und C, also N(3 | 2 | 0). M liegt 3 Einheiten senkrecht darüber: M(3 | 2 | 3). Beide Wege geben M(3 | 2 | 3). Summe: 3 + 2 + 3 = 8.", "form": "zwei_wege", "zaehlt": "ja", "r": 13584}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Rechteck mit den Seiten 4 cm und h cm dreht sich um die Seite mit der Länge h. Der entstehende Zylinder hat das Volumen 80π cm³. Wie lang ist h in Zentimetern?"}, "o": {"wert": 5, "einheit": "cm"}, "h": "Welche Seite liegt auf der Drehachse? Welche Seite wird beim Drehen zum Radius?", "w": "Die Seite h liegt auf der Achse und wird die Höhe des Zylinders. Die andere Seite, 4 cm, wird der Radius. V = π · r² · h = π · 16 · h = 80π, also 16h = 80 und h = 5. Probe: π · 16 · 5 = 80π.", "form": "umkehren", "zaehlt": "ja", "r": 13585}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Rechteck mit den Seiten 3 cm und 5 cm dreht sich um die 5-cm-Seite. Kim bestimmt den entstehenden Körper und sein Volumen. Zeile 1: Es entsteht ein Zylinder mit dem Radius 5 cm und der Höhe 3 cm. Zeile 2: Das Volumen ist V = π · r² · h = π · 25 · 3, also V = 75π cm³. Zeile 3: Die Grundfläche des Zylinders ist ein Kreis mit dem Durchmesser 10 cm. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Fertige eine Skizze an. Welche Seite liegt beim Drehen auf der Drehachse?", "w": "Die 5-cm-Seite liegt auf der Achse und wird die Höhe. Die andere Seite, 3 cm, wird der Radius. Zeile 1 vertauscht Radius und Höhe. Richtig ist V = π · 3² · 5 = 45π cm³. Die Zeilen 2 und 3 rechnen mit dem falschen Radius 5 cm.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13586}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Der Axialschnitt eines Zylinders ist ein Rechteck mit dem Flächeninhalt 60 cm². Der Zylinder ist 6 cm hoch. Wie groß ist sein Radius in Zentimetern?"}, "o": {"wert": 5, "einheit": "cm"}, "h": "Wie breit ist das Schnittrechteck im Vergleich zum Radius?", "w": "Der Axialschnitt ist ein Rechteck. Seine Breite ist der Durchmesser 2r, seine Höhe ist 6 cm. Aus 2r · 6 = 60 folgt 12r = 60 und r = 5. Probe: Durchmesser 10 cm, 10 · 6 = 60.", "form": "umkehren", "zaehlt": "ja", "r": 13587}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Die Zeichnung zeigt den Axialschnitt eines Zylinders. Die Breite des Rechtecks ist der Durchmesser der Grundfläche, seine Höhe ist die Höhe des Zylinders. Das Volumen ist V = n · π cm³. Welche Zahl ist n?", "grafik": {"typ": "figur", "punkte": {"A": [0, 0], "B": [6, 0], "C": [6, 2.5], "D": [0, 2.5]}, "flaeche": ["A", "B", "C", "D"], "linien": [["A", "B", "12 cm"], ["B", "C", "5 cm"]]}}, "o": {"wert": 180}, "h": "Aus der Breite im Schnitt erhältst du zuerst den Radius.", "w": "Die Breite 12 cm ist der Durchmesser, also ist r = 6 cm. Die Höhe ist 5 cm. V = π · r² · h = π · 36 · 5 = 180π cm³. Also ist n = 180.", "form": "bruecke", "zaehlt": "ja", "r": 13588}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Schuhkarton hat die Form eines Quaders. Alle drei Kantenlängen (Länge, Breite, Höhe) sind verschieden. Wie viele Symmetrieebenen hat der Karton?"}, "o": {"wert": 3}, "h": "Jede Symmetrieebene halbiert eine Kantenrichtung. Wie viele Kantenrichtungen gibt es?", "w": "Der Quader hat drei Kantenrichtungen. Je eine Ebene geht durch die Mitte und steht senkrecht zu einer Richtung. Das sind 3 Symmetrieebenen. Andere Ebenen, etwa durch gegenüberliegende Kanten, bilden den Quader nicht auf sich ab, weil die Kanten verschieden lang sind.", "form": "anwenden", "zaehlt": "ja", "r": 13589}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim zählt die Symmetrieebenen einer geraden Pyramide, deren Grundfläche ein regelmäßiges Sechseck ist. Zeile 1: Die Spitze liegt senkrecht über dem Mittelpunkt des Sechsecks. Zeile 2: Jede Symmetrieebene der Pyramide enthält die Höhe: Die Spiegelung erhält auch die sechseckige Grundfläche und deren Mittelpunkt. Spitze und Mittelpunkt bleiben also an ihrem Platz, deshalb liegt die Höhenlinie in der Spiegelebene. Zeile 3: Ein regelmäßiges Sechseck hat 6 Symmetrieachsen und die Pyramide hat zusätzlich die Grundfläche als Ebene. Das sind 7 Symmetrieebenen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wird die Pyramide an der Ebene der Grundfläche auf sich selbst abgebildet? Wo liegt die Spitze nach dem Spiegeln?", "w": "Die Zeilen 1 und 2 stimmen. In Zeile 3 ist die Grundfläche keine Symmetrieebene: Die Spitze würde unter die Grundfläche gespiegelt und die Pyramide fiele nicht auf sich. Jede der 6 Achsen des Sechsecks gibt zusammen mit der Höhe eine Symmetrieebene. Es gibt also 6 Symmetrieebenen, nicht 7.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 13590}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 132 then fehler := fehler || ('zusammen ' || gesamt || ' statt 132')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (3, 5, 16, 17, 20, 31, 34, 72, 305, 306, 308, 310) group by 1 order by 1;
